/* Tradução do Novo Mundo (edição de estudo), extraída do JW Library local. */
window.NWT = {"books": {"1": "Gênesis", "16": "Neemias", "17": "Ester", "19": "Salmo", "20": "Provérbios", "23": "Isaías", "26": "Ezequiel", "29": "Joel", "36": "Sofonias", "38": "Zacarias", "39": "Malaquias", "40": "Mateus", "42": "Lucas", "43": "João", "44": "Atos", "45": "Romanos", "46": "1 Coríntios", "48": "Gálatas", "58": "Hebreus", "66": "Apocalipse"}, "verses": {"1:11:1": "Toda a terra continuava a ter um só idioma e um só conjunto de palavras.", "1:11:2": "Ao migrarem para o leste, os homens descobriram uma planície na terra de Sinear e passaram a morar ali.", "1:11:3": "Então disseram uns aos outros: “Venham! Vamos fazer tijolos e cozê-los no fogo.” Assim, usavam tijolos em vez de pedra, e betume como argamassa.", "1:11:4": "Disseram então: “Venham! Vamos construir uma cidade para nós e uma torre cujo topo chegue aos céus, e vamos fazer para nós um nome célebre; assim não seremos espalhados por toda a face da terra.”", "1:11:5": "Jeová desceu então para ver a cidade e a torre que os filhos dos homens tinham construído.", "1:11:6": "E Jeová disse: “Eles são um só povo, com um só idioma, e vejam o que estão fazendo. Agora, nada do que planejem fazer será impossível para eles.", "1:11:7": "Vamos! Desçamos e confundamos o seu idioma, para que não entendam o idioma um do outro.”", "1:11:8": "Assim, Jeová os espalhou dali por toda a face da terra, e, por fim, eles deixaram de construir a cidade.", "1:11:9": "É por isso que a cidade recebeu o nome de Babel, porque Jeová confundiu ali o idioma de toda a terra, e Jeová os espalhou dali por toda a face da terra.", "1:11:10": "Esta é a história de Sem. Sem tinha 100 anos de idade quando se tornou pai de Arpaxade, dois anos após o dilúvio.", "1:11:11": "Depois de se tornar pai de Arpaxade, Sem viveu mais 500 anos. E ele se tornou pai de filhos e de filhas.", "1:11:12": "Arpaxade viveu 35 anos e então se tornou pai de Selá.", "1:11:13": "Depois de se tornar pai de Selá, Arpaxade viveu mais 403 anos. E ele se tornou pai de filhos e de filhas.", "1:11:14": "Selá viveu 30 anos e então se tornou pai de Éber.", "1:11:15": "Depois de se tornar pai de Éber, Selá viveu mais 403 anos. E ele se tornou pai de filhos e de filhas.", "1:11:16": "Éber viveu 34 anos e então se tornou pai de Pelegue.", "1:11:17": "Depois de se tornar pai de Pelegue, Éber viveu mais 430 anos. E ele se tornou pai de filhos e de filhas.", "1:11:18": "Pelegue viveu 30 anos e então se tornou pai de Reú.", "1:11:19": "Depois de se tornar pai de Reú, Pelegue viveu mais 209 anos. E ele se tornou pai de filhos e de filhas.", "1:11:20": "Reú viveu 32 anos e então se tornou pai de Serugue.", "1:11:21": "Depois de se tornar pai de Serugue, Reú viveu mais 207 anos. E ele se tornou pai de filhos e de filhas.", "1:11:22": "Serugue viveu 30 anos e então se tornou pai de Naor.", "1:11:23": "Depois de se tornar pai de Naor, Serugue viveu mais 200 anos. E ele se tornou pai de filhos e de filhas.", "1:11:24": "Naor viveu 29 anos e então se tornou pai de Tera.", "1:11:25": "Depois de se tornar pai de Tera, Naor viveu mais 119 anos. E ele se tornou pai de filhos e de filhas.", "1:11:26": "Tera viveu 70 anos, e depois se tornou pai de Abrão, Naor e Harã.", "1:11:27": "Esta é a história de Tera. Tera tornou-se pai de Abrão, Naor e Harã; e Harã tornou-se pai de Ló.", "1:11:28": "Harã morreu na sua terra natal, em Ur dos caldeus, enquanto Tera, seu pai, ainda estava vivo.", "1:11:29": "Abrão e Naor tomaram para si esposas. O nome da esposa de Abrão era Sarai, e o nome da esposa de Naor era Milca, filha de Harã, pai de Milca e de Iscá.", "1:11:30": "Sarai era estéril; não tinha filhos.", "1:11:31": "Tera tomou então seu filho Abrão, seu neto Ló, filho de Harã, e sua nora Sarai, esposa do seu filho Abrão; e esses saíram com ele de Ur dos caldeus, a fim de ir para a terra de Canaã. Com o tempo chegaram a Harã e passaram a morar ali.", "1:11:32": "Os dias de Tera foram 205 anos. Tera morreu então em Harã.", "19:9:1": "Vou louvar-te de todo o meu coração, ó Jeová; Vou relatar todas as tuas obras maravilhosas.", "19:9:2": "Vou alegrar-me e exultar em ti; Vou cantar louvores ao teu nome, ó Altíssimo.", "19:9:3": "Quando os meus inimigos recuarem, Tropeçarão e morrerão diante de ti.", "19:9:4": "Pois tu defendes a minha causa justa; Sentas no teu trono, julgando com justiça.", "19:9:5": "Censuraste nações e destruíste os maus Apagando para todo o sempre o nome deles.", "19:9:6": "Os inimigos sofreram destruição eterna; Desarraigaste as cidades deles, E toda lembrança deles desaparecerá.", "19:9:7": "Mas Jeová está no seu trono para sempre; Ele estabeleceu firmemente o seu trono para fazer justiça.", "19:9:8": "Ele julgará a terra habitada com retidão; Pronunciará sentenças justas para as nações.", "19:9:9": "Jeová se tornará um refúgio seguro para os oprimidos, Um refúgio seguro em tempos de aflição.", "19:9:10": "Os que conhecem o teu nome confiarão em ti; Nunca abandonarás os que te buscam, ó Jeová.", "19:9:11": "Cantem louvores a Jeová, que mora em Sião; Tornem conhecidos entre os povos os seus feitos.", "19:9:12": "Pois Aquele que vinga o sangue dos aflitos se lembra deles; Não se esquecerá do seu clamor.", "19:9:13": "Mostra-me favor, ó Jeová; vê a minha aflição, causada pelos que me odeiam, Tu, que me ergues dos portões da morte,", "19:9:14": "Para que eu declare os teus atos louváveis nos portões da filha de Sião E me alegre com os teus atos de salvação.", "19:9:15": "As nações caíram na cova que fizeram; Seu próprio pé ficou preso na rede que esconderam.", "19:9:16": "Jeová é conhecido pelos julgamentos que executa. Os maus foram enlaçados pela obra das suas próprias mãos. Higaiom. (Selá)", "19:9:17": "Os maus recuarão em direção à Sepultura, Todas as nações que se esquecem de Deus.", "19:9:18": "Mas os pobres não ficarão esquecidos para sempre, E a esperança dos mansos jamais acabará.", "19:9:19": "Levanta-te, ó Jeová! Não deixes que o homem mortal prevaleça. Que as nações sejam julgadas na tua presença.", "19:9:20": "Enche-as de medo, ó Jeová; Que as nações saibam que são apenas homens mortais. (Selá)", "19:68:1": "Que Deus se levante, e que seus inimigos sejam espalhados, Que todos os que o odeiam fujam de diante dele.", "19:68:2": "Que tu os expulses assim como o vento leva a fumaça embora. Assim como a cera derrete na presença do fogo, Assim sejam eliminados os maus na presença de Deus.", "19:68:3": "Mas que os justos se alegrem; Que fiquem radiantes diante de Deus; Que exultem com alegria.", "19:68:4": "Cantem a Deus; cantem louvores ao seu nome. Cantem àquele que cavalga através das planícies desérticas. Jah é o seu nome! Alegrem-se diante dele!", "19:68:5": "Pai dos órfãos e protetor das viúvas É Deus na sua santa morada.", "19:68:6": "Deus dá aos que estão sós um lar onde morar; Conduz os prisioneiros à liberdade e à prosperidade. Mas os obstinados têm de viver numa terra seca.", "19:68:7": "Ó Deus, quando conduziste o teu povo, Quando marchaste através do deserto, (Selá)", "19:68:8": "A terra tremeu; Os céus derramaram chuva por causa de Deus; O monte Sinai tremeu por causa de Deus, o Deus de Israel.", "19:68:9": "Fizeste chover em abundância, ó Deus; Revigoraste teu povo exausto.", "19:68:10": "Eles moraram no teu acampamento; Na tua bondade, fizeste provisões para o pobre, ó Deus.", "19:68:11": "Jeová dá a ordem; As mulheres que proclamam as boas novas são um grande exército.", "19:68:12": "Os reis e os seus exércitos fogem, eles fogem! Aquela que fica em casa participa do despojo.", "19:68:13": "Embora vocês se tenham deitado entre as fogueiras do acampamento, Haverá as asas de uma pomba, revestidas de prata, Com plumas de ouro fino.", "19:68:14": "Quando o Todo-Poderoso espalhou os reis desta terra, Nevou em Zalmom.", "19:68:15": "A montanha de Basã é uma montanha de Deus; A montanha de Basã é uma montanha de picos.", "19:68:16": "Ó montanhas de picos, por que estão olhando com inveja Para o monte que Deus escolheu para morar? Sim, Jeová residirá ali para sempre.", "19:68:17": "Os carros de guerra de Deus são dezenas de milhares, milhares de milhares. Jeová veio do monte Sinai para o lugar santo.", "19:68:18": "Subiste ao alto; Levaste contigo cativos; Tomaste dádivas em forma de homens, Sim, até mesmo homens obstinados, para residires entre eles, ó Jah, Deus.", "19:68:19": "Louvado seja Jeová, que diariamente leva a nossa carga, O verdadeiro Deus, que é a nossa salvação. (Selá)", "19:68:20": "O verdadeiro Deus é para nós um Deus que salva; Jeová, o Soberano Senhor, livra da morte.", "19:68:21": "Sim, Deus esmagará a cabeça dos seus inimigos, O crânio de todo aquele que continua no erro.", "19:68:22": "Jeová disse: “Eu os trarei de volta de Basã; Eu os trarei de volta das profundezas do mar,", "19:68:23": "A fim de que você encharque os pés no sangue dos inimigos, E os seus cães possam lamber o sangue deles.”", "19:68:24": "Eles veem os teus desfiles triunfais, ó Deus, Os desfiles do meu Deus, meu Rei, entrando no lugar santo.", "19:68:25": "Os cantores vão na frente; os músicos, tocando instrumentos de cordas, atrás deles; No meio estão as jovens tocando pandeiros.", "19:68:26": "Em multidões reunidas, louvem a Deus; Louvem a Jeová, vocês que são da Fonte de Israel.", "19:68:27": "Ali Benjamim, o mais novo, domina sobre eles, Também os príncipes de Judá, com sua multidão gritando de alegria, Os príncipes de Zebulão, os príncipes de Naftali.", "19:68:28": "Seu Deus decretou que você será forte. Mostra a tua força, ó Deus, tu que tens agido em nosso favor.", "19:68:29": "Por causa do teu templo em Jerusalém, Reis trarão presentes a ti.", "19:68:30": "Censura as feras dos juncos, A manada de touros e os seus bezerros, Até que os povos se curvem e tragam peças de prata. Mas ele espalha os povos que têm prazer na guerra.", "19:68:31": "Objetos de bronze serão trazidos do Egito; Cuche se apressará em oferecer dádivas a Deus.", "19:68:32": "Ó reinos da terra, cantem a Deus, Cantem louvores a Jeová, (Selá)", "19:68:33": "Aquele que cavalga sobre o antigo céu dos céus. Escutem! Ele troveja com a sua voz, sua voz poderosa.", "19:68:34": "Reconheçam a força de Deus. Sua majestade está sobre Israel, E sua força está nos céus.", "19:68:35": "Do seu grandioso santuário, Deus inspira temor. Ele é o Deus de Israel, Que dá força e poder ao povo. Louvado seja Deus.", "19:110:1": "Jeová declarou ao meu Senhor: “Sente-se à minha direita, Até que eu ponha os seus inimigos debaixo dos seus pés.”", "19:110:2": "Jeová estenderá desde Sião o cetro do seu poder, dizendo: “Domine no meio dos seus inimigos.”", "19:110:3": "Seu povo se apresentará voluntariamente no dia da sua força militar. Em esplêndida santidade, vindos do amanhecer, O senhor recebe o seu exército de jovens como gotas de orvalho.", "19:110:4": "Jeová fez um juramento, e não voltará atrás: “Você é sacerdote para sempre À maneira de Melquisedeque!”", "19:110:5": "Jeová estará à sua direita; Ele esmagará reis no dia da Sua ira.", "19:110:6": "Executará julgamento contra as nações; Amontoará cadáveres. Ele esmagará o líder de uma terra vasta.", "19:110:7": "Ao longo do caminho, ele beberá da corrente de água. Por isso, manterá a cabeça erguida.", "19:135:1": "Louvem a Jah! Louvem o nome de Jeová; Deem louvores, servos de Jeová,", "19:135:2": "Vocês que estão servindo na casa de Jeová, Nos pátios da casa do nosso Deus.", "19:135:3": "Louvem a Jah, porque Jeová é bom. Cantem louvores ao seu nome, porque é agradável.", "19:135:4": "Pois Jah escolheu Jacó para si, Israel como sua propriedade especial.", "19:135:5": "Eu bem sei que Jeová é grande; Nosso Senhor é maior do que todos os outros deuses.", "19:135:6": "Jeová faz tudo o que deseja fazer Nos céus e na terra, nos mares e em todas as profundezas.", "19:135:7": "Ele faz subir nuvens desde os confins da terra; Faz os relâmpagos para a chuva; Faz o vento sair dos Seus depósitos.", "19:135:8": "Ele matou os primogênitos do Egito, Tanto dos homens como dos animais.", "19:135:9": "Realizou sinais e milagres no seu meio, ó Egito, Contra Faraó e todos os seus servos.", "19:135:10": "Ele derrotou muitas nações E matou reis poderosos:", "19:135:11": "Siom, rei dos amorreus, Ogue, rei de Basã, E todos os reinos de Canaã.", "19:135:12": "Ele deu a terra deles como herança, Uma herança a Israel, seu povo.", "19:135:13": "Ó Jeová, teu nome permanece para sempre. Ó Jeová, tua fama dura por todas as gerações.", "19:135:14": "Pois Jeová defenderá o seu povo E terá compaixão dos seus servos.", "19:135:15": "Os ídolos das nações são prata e ouro, Trabalho de mãos humanas.", "19:135:16": "Têm boca, mas não podem falar; Olhos, mas não podem ver;", "19:135:17": "Têm orelhas, mas não podem ouvir. Não há respiração na sua boca.", "19:135:18": "As pessoas que os fazem ficarão iguais a eles, E também todos os que neles confiam.", "19:135:19": "Ó casa de Israel, louve a Jeová. Ó casa de Arão, louve a Jeová.", "19:135:20": "Ó casa de Levi, louve a Jeová. Vocês que temem a Jeová, louvem a Jeová.", "19:135:21": "Que Jeová seja louvado em Sião; Ele, que reside em Jerusalém. Louvem a Jah!", "20:18:1": "Quem se isola busca seus desejos egoístas; Rejeita toda a sabedoria prática.", "20:18:2": "O tolo não tem prazer no entendimento; Prefere divulgar o que tem no coração.", "20:18:3": "Com os maus vem o desprezo, E com a desonra vem a humilhação.", "20:18:4": "As palavras da boca do homem são como águas profundas. A fonte da sabedoria é como um riacho transbordante.", "20:18:5": "Não é bom mostrar parcialidade a favor de quem é mau, Nem privar o justo da justiça.", "20:18:6": "As palavras do tolo provocam discussões, E sua boca atrai uma surra.", "20:18:7": "A boca do tolo é sua ruína, E seus lábios são uma armadilha para sua vida.", "20:18:8": "As palavras do caluniador são como petiscos saborosos, Que são engolidos com facilidade e descem direto para o estômago.", "20:18:9": "Quem é preguiçoso no seu trabalho É irmão de quem causa destruição.", "20:18:10": "O nome de Jeová é uma torre forte. O justo corre para dentro dela e recebe proteção.", "20:18:11": "A riqueza do rico é a sua cidade fortificada; Na sua imaginação ela é como uma muralha protetora.", "20:18:12": "Antes da queda, o coração do homem é arrogante; E antes da glória há humildade.", "20:18:13": "Responder antes de ouvir os fatos É tolice e resulta em humilhação.", "20:18:14": "O espírito do homem pode sustentá-lo na sua doença, Mas quem pode suportar o espírito abatido?", "20:18:15": "O coração de quem tem entendimento adquire conhecimento, E o ouvido dos sábios busca o conhecimento.", "20:18:16": "Um presente abre as portas para quem o dá E lhe permite ter acesso a pessoas importantes.", "20:18:17": "O primeiro a apresentar a sua causa parece estar certo, Até que vem a outra parte e o interroga.", "20:18:18": "Lançar sortes acaba com as disputas E decide questões entre adversários poderosos.", "20:18:19": "Um irmão ofendido é mais inacessível do que uma cidade fortificada, E há disputas que são como as trancas de uma fortaleza.", "20:18:20": "Dos frutos das suas palavras o homem encherá o seu estômago; Ele se fartará com o produto dos seus lábios.", "20:18:21": "Morte e vida estão no poder da língua; Os que gostam de usá-la comerão os seus frutos.", "20:18:22": "Quem encontra uma boa esposa encontra algo bom, E recebe o favor de Jeová.", "20:18:23": "O pobre fala suplicando, Mas o rico responde de modo duro.", "20:18:24": "Alguns amigos estão prontos para acabar um com o outro, Mas há um amigo que se apega mais do que um irmão.", "23:2:1": "Foi isto que Isaías, filho de Amoz, viu a respeito de Judá e Jerusalém:", "23:2:2": "Na parte final dos dias, O monte da casa de Jeová Ficará firmemente estabelecido acima do cume dos montes, E será elevado acima das colinas, E todas as nações afluirão a ele.", "23:2:3": "E muitos povos irão e dirão: “Venham, subamos ao monte de Jeová, À casa do Deus de Jacó. Ele nos instruirá sobre os seus caminhos, E nós andaremos nas suas veredas.” Pois de Sião sairá a lei, E de Jerusalém a palavra de Jeová.", "23:2:4": "Ele fará julgamento entre as nações E resolverá as questões referentes a muitos povos. Eles transformarão as suas espadas em arados, E as suas lanças em podadeiras. Nação não levantará espada contra nação, Nem aprenderão mais a guerra.", "23:2:5": "Venha, ó casa de Jacó, Andemos na luz de Jeová.", "23:2:6": "Pois abandonaste o teu povo, a casa de Jacó, Porque a sua terra ficou cheia das coisas do Oriente; Eles praticam a magia, como os filisteus, E há muitos filhos de estrangeiros entre eles.", "23:2:7": "Sua terra está cheia de prata e de ouro, E não há limite para os seus tesouros. Sua terra está cheia de cavalos, E não há limite para os seus carros de guerra.", "23:2:8": "Sua terra está cheia de deuses que nada valem. Curvam-se diante do trabalho das suas próprias mãos, Diante do que os seus próprios dedos fizeram.", "23:2:9": "Assim os homens se rebaixam e são humilhados, E não é possível que os perdoes.", "23:2:10": "Entre na rocha e esconda-se no pó Por causa da presença atemorizante de Jeová E do esplendor da sua majestade.", "23:2:11": "Os olhos dos arrogantes serão humilhados, E os homens orgulhosos serão rebaixados. Somente Jeová será enaltecido naquele dia.", "23:2:12": "Porque é o dia que pertence a Jeová dos exércitos. Vem sobre todos os orgulhosos e altivos, Sobre todos, tanto os de condição elevada como os humildes,", "23:2:13": "Sobre todos os cedros do Líbano, que são altivos e elevados, E sobre todos os carvalhos de Basã,", "23:2:14": "Sobre todos os montes altivos E sobre todas as colinas elevadas,", "23:2:15": "Sobre toda torre alta e toda muralha fortificada,", "23:2:16": "Sobre todos os navios de Társis E sobre todos os barcos desejáveis.", "23:2:17": "Os homens orgulhosos serão rebaixados, E os homens arrogantes serão humilhados. Somente Jeová será enaltecido naquele dia.", "23:2:18": "Os deuses que nada valem desaparecerão completamente.", "23:2:19": "E as pessoas entrarão nas cavernas das rochas E nos buracos no chão, Por causa da presença atemorizante de Jeová E do esplendor da sua majestade, Quando ele se levantar para fazer a terra tremer de medo.", "23:2:20": "Naquele dia, os homens pegarão seus deuses de prata e de ouro que nada valem, Que fizeram para se curvar diante deles, E os lançarão aos ratos e aos morcegos,", "23:2:21": "E entrarão nos buracos das rochas E nas fendas dos rochedos, Por causa da presença atemorizante de Jeová E do esplendor da sua majestade, Quando ele se levantar para fazer a terra tremer de medo.", "23:2:22": "Para seu próprio bem, parem de confiar no mero homem, Que é apenas o fôlego de suas narinas. Por que ele deveria ser levado em conta?", "23:56:1": "Assim diz Jeová: “Pratiquem a justiça e façam o que é certo, Pois a minha salvação logo chegará E a minha justiça será revelada.", "23:56:2": "Feliz o homem que age assim, E o filho do homem que se apega a isso, Que guarda o sábado e não o profana, E que refreia a sua mão de todo tipo de maldade.", "23:56:3": "O estrangeiro que se une a Jeová não deve dizer: ‘Sem dúvida, Jeová me separará do seu povo.’ E o eunuco não deve dizer: ‘Veja! Sou uma árvore seca.’”", "23:56:4": "Pois assim diz Jeová aos eunucos que guardam os meus sábados, que escolhem fazer o que me agrada e que se apegam ao meu pacto:", "23:56:5": "“Eu lhes darei na minha casa e dentro das minhas muralhas um monumento e um nome, Algo melhor do que filhos e filhas; Eu lhes darei um nome eterno, Que não será esquecido.", "23:56:6": "Quanto aos estrangeiros que se unem a Jeová para servi-lo, Para amar o nome de Jeová E para ser seus servos, Todos os que guardam o sábado e não o profanam, E que se apegam ao meu pacto,", "23:56:7": "Também a esses vou trazer ao meu santo monte E fazê-los alegrar-se dentro da minha casa de oração. Suas ofertas queimadas e seus sacrifícios serão aceitos no meu altar. Pois a minha casa será chamada casa de oração para todos os povos.”", "23:56:8": "O Soberano Senhor Jeová, que está reunindo os dispersos de Israel, diz: “Reunirei a ele outros além daqueles que já foram reunidos.”", "23:56:9": "Todos vocês, animais selvagens, venham comer; Todos vocês, animais da floresta!", "23:56:10": "Os vigias são cegos, não percebem nada. Todos eles são cães mudos, incapazes de latir. Estão ofegantes, deitados; gostam de cochilar.", "23:56:11": "São cães vorazes, Nunca se satisfazem. São pastores que não têm entendimento. Todos eles seguem o seu próprio caminho; Cada um deles, sem exceção, busca o seu próprio lucro desonesto e diz:", "23:56:12": "“Venham! Vou buscar vinho; Bebamos até ficar embriagados. E amanhã será como hoje, só que muito melhor!”", "26:38:1": "Recebi novamente a palavra de Jeová:", "26:38:2": "“Filho do homem, volte seu rosto contra Gogue da terra de Magogue, maioral-chefe de Meseque e Tubal, e profetize contra ele.", "26:38:3": "Diga: ‘Assim diz o Soberano Senhor Jeová: “Eu estou contra você, ó Gogue, maioral-chefe de Meseque e Tubal.", "26:38:4": "Farei você dar meia-volta, porei ganchos nas suas mandíbulas e o farei sair com toda a sua força militar, cavalos e cavaleiros, todos eles vestidos com esplendor, um exército numeroso com escudos grandes e pequenos, todos eles armados com espadas.", "26:38:5": "Pérsia, Etiópia e Pute estão com eles, todos com escudos e capacetes;", "26:38:6": "também Gômer e todas as suas tropas, a casa de Togarma, das partes mais distantes do norte, junto com todas as suas tropas — sim, muitos povos estão com você.", "26:38:7": "“‘“Aprontem-se, estejam preparados, você e todos os exércitos que se juntaram a você, e você será o comandante deles.", "26:38:8": "“‘“Você receberá atenção depois de muitos dias. No fim dos anos, você invadirá a terra cujo povo foi restabelecido da devastação da espada, que foi reunido dentre muitos povos e trazido aos montes de Israel, os quais por muito tempo tinham ficado devastados. Os habitantes dessa terra foram trazidos de volta dentre as nações e todos eles moram em segurança.", "26:38:9": "Você virá contra eles como uma tempestade e cobrirá a terra como nuvens, você, todas as suas tropas e os muitos povos que o acompanham.”’", "26:38:10": "“Assim diz o Soberano Senhor Jeová: ‘Naquele dia surgirão ideias no seu coração e você planejará uma trama perversa.", "26:38:11": "Você dirá: “Invadirei a terra de povoados desprotegidos. Irei contra os que vivem em segurança, sem perturbação; todos eles moram em povoados sem muralhas, trancas ou portões.”", "26:38:12": "Seu objetivo será tomar muito despojo e espólio, será atacar os lugares devastados agora repovoados e um povo que foi reunido dentre as nações e está acumulando riquezas e bens, morando no meio da terra.", "26:38:13": "“‘Sabá e Dedã, os mercadores de Társis e todos os seus guerreiros lhe dirão: “Por acaso você fará essa invasão para tomar muito despojo e espólio? Você reuniu os seus exércitos para levar embora prata e ouro, para saquear riquezas e bens, para tomar um enorme despojo?”’", "26:38:14": "“Portanto, filho do homem, profetize o seguinte a Gogue: ‘Assim diz o Soberano Senhor Jeová: “Naquele dia, quando o meu povo Israel estiver morando em segurança, será que você não ficará sabendo disso?", "26:38:15": "Você virá do seu lugar, das partes mais distantes do norte, acompanhado de muitos povos, todos eles montados em cavalos, um grande exército, uma numerosa força militar.", "26:38:16": "Você virá contra o meu povo Israel como nuvens cobrindo a terra. Na parte final dos dias vou trazê-lo contra a minha terra, para que as nações me conheçam quando eu me santificar diante dos olhos delas por meio de você, ó Gogue.”’", "26:38:17": "“Assim diz o Soberano Senhor Jeová: ‘Não é você aquele de quem falei no passado por meio dos meus servos, os profetas de Israel, que durante muitos anos profetizaram que você seria trazido contra eles?’", "26:38:18": "“‘Naquele dia, o dia em que Gogue invadir a terra de Israel’, diz o Soberano Senhor Jeová, ‘o meu grande furor se acenderá.", "26:38:19": "No meu zelo, no fogo da minha fúria, eu falarei; e naquele dia ocorrerá um grande terremoto na terra de Israel.", "26:38:20": "Por minha causa tremerão os peixes do mar, as aves do céu, os animais selvagens, todos os répteis que rastejam sobre o solo e todos os homens na face da terra. Os montes serão derrubados, os penhascos desmoronarão, e todas as muralhas cairão por terra.’", "26:38:21": "“‘Vou convocar contra Gogue uma espada em todas as minhas montanhas’, diz o Soberano Senhor Jeová. ‘A espada de cada um será contra o seu próprio irmão.", "26:38:22": "Vou trazer o meu julgamento contra ele com peste e derramamento de sangue. Farei cair uma chuva torrencial, pedras de granizo, fogo e enxofre sobre ele, sobre suas tropas e sobre os muitos povos que o acompanham.", "26:38:23": "Eu certamente me magnificarei, me santificarei e me darei a conhecer diante dos olhos de muitas nações; e terão de saber que eu sou Jeová.’", "29:2:1": "“Toquem a buzina em Sião! Deem um grito de guerra no meu santo monte. Que todos os habitantes desta terra tremam, Pois o dia de Jeová está chegando! Está próximo!", "29:2:2": "É um dia de escuridão e de trevas, Um dia de nuvens e de densas trevas. É como a luz da aurora se espalhando sobre os montes. Há um povo numeroso e poderoso; Nunca existiu um povo como ele, E nunca mais haverá outro, Pelos anos de todas as gerações.", "29:2:3": "À frente dele um fogo devora, E atrás dele as chamas consomem. A terra à sua frente é como o jardim do Éden, Mas atrás dele é um deserto desolado, E nada pode escapar.", "29:2:4": "Sua aparência é como a aparência de cavalos, E eles correm como cavalos de guerra.", "29:2:5": "O som deles é como o de carros de guerra quando saltam no cume dos montes, Como o estalo de um fogo ardente que consome a palha. São como um povo forte posto em formação de batalha.", "29:2:6": "Por causa deles, povos ficarão aflitos. Todos os rostos expressarão angústia.", "29:2:7": "Eles atacam como guerreiros, Escalam a muralha como soldados, Cada um se mantém no seu próprio curso, E eles não se desviam do seu caminho.", "29:2:8": "Não empurram uns aos outros; Cada homem avança no seu rumo. Se as armas fazem alguns cair, Os outros não desfazem a formação.", "29:2:9": "Invadem a cidade, correm sobre a muralha. Sobem às casas, entram pelas janelas como ladrões.", "29:2:10": "Diante deles a terra treme e os céus se abalam. O sol e a lua ficaram escuros, E as estrelas perderam o brilho.", "29:2:11": "Jeová levantará a sua voz perante o seu exército, pois o seu acampamento é muito numeroso. Pois aquele que cumpre a Sua palavra é forte; Pois o dia de Jeová é grande e muito atemorizante. Quem poderá suportá-lo?”", "29:2:12": "“Por isso, enquanto é tempo”, diz Jeová, “voltem para mim de todo o coração, Com jejum, choro e lamento.", "29:2:13": "Rasguem o seu coração, e não as suas roupas, E voltem para Jeová, seu Deus, Pois ele é compassivo e misericordioso, paciente e cheio de amor leal, E reconsiderará a calamidade.", "29:2:14": "Quem sabe ele não voltará atrás e reconsiderará, E deixará sobrar uma bênção, Uma oferta de cereais e uma oferta de bebida para Jeová, seu Deus?", "29:2:15": "Toquem a buzina em Sião! Proclamem um jejum; convoquem uma assembleia solene.", "29:2:16": "Reúnam o povo, santifiquem a congregação. Convoquem os homens idosos, reúnam as crianças e os bebês. Que o noivo saia do seu aposento interno, e a noiva da sua câmara nupcial.", "29:2:17": "Entre o pórtico e o altar, Que chorem os sacerdotes, os servos de Jeová, e digam: ‘Tem pena do teu povo, ó Jeová, Não faças da tua herança um objeto de zombaria, Deixando as nações dominar sobre eles. Por que os povos deveriam dizer: “Onde está o Deus deles?”’", "29:2:18": "Então Jeová será zeloso para com a sua terra E terá compaixão do seu povo.", "29:2:19": "Jeová responderá ao seu povo: ‘Estou lhes enviando cereal, vinho novo e azeite, E vocês ficarão plenamente satisfeitos; Não farei mais de vocês um alvo de insultos entre as nações.", "29:2:20": "Afastarei para longe de vocês aquele que vem do norte; Eu o dispersarei por um deserto árido e desolado, Com a vanguarda dele voltada para o mar oriental E a retaguarda para o mar ocidental. O mau cheiro dele subirá, O fedor dele continuará a subir, Pois Ele fará coisas grandiosas.’", "29:2:21": "Não tenha medo, ó terra. Exulte e alegre-se, pois Jeová fará coisas grandiosas.", "29:2:22": "Não tenham medo, animais selvagens, Pois as pastagens do deserto ficarão verdes, E as árvores darão frutos; A figueira e a videira produzirão abundantemente.", "29:2:23": "Exultem e alegrem-se em Jeová, seu Deus, filhos de Sião; Pois ele lhes dará a chuva do outono na medida certa E fará cair sobre vocês chuvas abundantes, A chuva do outono e a chuva da primavera, assim como antes.", "29:2:24": "As eiras ficarão cheias de cereal puro, E os lagares transbordarão de vinho novo e de azeite.", "29:2:25": "E vou compensar-lhes os anos Que foram comidos pela nuvem de gafanhotos, pelo gafanhoto sem asas, pelo gafanhoto voraz e pelo gafanhoto devorador, Meu grande exército que enviei entre vocês.", "29:2:26": "Vocês certamente comerão até ficar satisfeitos E louvarão o nome de Jeová, seu Deus, Que fez maravilhas por vocês; Meu povo nunca mais será envergonhado.", "29:2:27": "E vocês terão de saber que eu estou no meio de Israel E que eu sou Jeová, seu Deus — não há outro! Meu povo nunca mais será envergonhado.", "29:2:28": "Depois disso, derramarei meu espírito sobre todo tipo de pessoas, E os filhos e as filhas de vocês profetizarão, Os homens idosos entre vocês terão sonhos, E os jovens entre vocês terão visões.", "29:2:29": "E até mesmo sobre meus escravos e minhas escravas Derramarei meu espírito naqueles dias.", "29:2:30": "E realizarei milagres nos céus e na terra: Sangue, fogo e colunas de fumaça.", "29:2:31": "O sol será transformado em escuridão e a lua em sangue, Antes de chegar o grande e atemorizante dia de Jeová.", "29:2:32": "E todo aquele que invocar o nome de Jeová será salvo; Pois no monte Sião e em Jerusalém estarão os que escaparem, assim como Jeová disse, Os sobreviventes que Jeová está chamando.”", "36:3:1": "Ai da cidade rebelde, impura, opressiva!", "36:3:2": "Ela não obedece nenhuma voz, nem aceita nenhuma disciplina. Não confia em Jeová, nem se achega ao seu Deus.", "36:3:3": "Seus príncipes no meio dela são leões que rugem. Seus juízes são lobos da noite; Não deixam nem mesmo um osso para roer no dia seguinte.", "36:3:4": "Seus profetas são insolentes, traidores. Seus sacerdotes profanam o que é santo; Eles fazem violência à lei.", "36:3:5": "Jeová é justo e está no meio dela; ele não faz o que é errado. Manhã após manhã ele torna conhecidas as suas decisões judiciais, Sem falhar, como a luz do dia. Mas o injusto não sente vergonha.", "36:3:6": "“Eu destruí nações; suas torres de ângulo ficaram desoladas. Devastei suas ruas, e ninguém mais passa por elas. Suas cidades ficaram em ruínas, sem ninguém, sem nenhum habitante.", "36:3:7": "Eu disse a ela: ‘Certamente você me temerá e aceitará a disciplina’, Para que a morada dela não seja destruída, Pois eu ajustarei contas com ela por todas essas coisas. Mas eles estavam ainda mais ansiosos para agir de modo corrupto.", "36:3:8": "‘Portanto, fiquem à espera de mim’, diz Jeová, ‘Até o dia em que eu me levantar para tomar despojo, Pois a minha decisão judicial é ajuntar nações e reunir reinos, Para derramar sobre eles a minha indignação, toda a minha ira ardente; Pois toda a terra será consumida pelo fogo do meu zelo.", "36:3:9": "Naquele tempo, mudarei a língua dos povos para uma língua pura, Para que todos eles possam invocar o nome de Jeová, A fim de servi-lo ombro a ombro.’", "36:3:10": "Os que me suplicam, a filha do meu povo espalhado, Vão me trazer uma dádiva desde a região dos rios da Etiópia.", "36:3:11": "Naquele dia você não será envergonhada Por causa de todos os seus atos de rebeldia contra mim, Porque removerei do seu meio os orgulhosos arrogantes, E você nunca mais será arrogante no meu santo monte.", "36:3:12": "Deixarei um povo humilde e modesto restar no seu meio, E eles se refugiarão no nome de Jeová.", "36:3:13": "Os que restarem de Israel não farão o que é mau; Não falarão mentiras, nem terão na boca uma língua falsa; Eles se alimentarão e se deitarão, sem que ninguém os faça ter medo.”", "36:3:14": "Grite de júbilo, ó filha de Sião! Grite triunfantemente, ó Israel! Alegre-se e exulte de todo o coração, ó filha de Jerusalém!", "36:3:15": "Jeová removeu os julgamentos contra você. Fez o seu inimigo recuar. O Rei de Israel, Jeová, está no seu meio. Você não temerá mais nenhuma calamidade.", "36:3:16": "Naquele dia se dirá a Jerusalém: “Não tenha medo, ó Sião. Não deixe que as suas mãos se abaixem.", "36:3:17": "Jeová, seu Deus, está no seu meio. Como um valente guerreiro, ele salvará. Por sua causa ele exultará com grande alegria. Ele ficará em silêncio no seu próprio amor. Jubilará por sua causa com gritos de alegria.", "36:3:18": "Reunirei os que estão tristes por estarem ausentes das suas festividades; Eles ficaram longe de você enquanto suportavam desonra por causa dela.", "36:3:19": "Naquele tempo agirei contra todos os que oprimem você; Salvarei os que mancam E reunirei os que estão espalhados. Farei deles um motivo de louvor e fama Em toda a terra onde foram envergonhados.", "36:3:20": "Naquele tempo, trarei vocês de volta, No tempo em que eu os reunir. Pois farei de vocês um motivo de fama e louvor entre todos os povos da terra, Quando eu trouxer de volta os seus cativos diante dos seus olhos”, diz Jeová.", "38:2:1": "E levantei os olhos e vi um homem com uma corda de medir na mão.", "38:2:2": "Perguntei, então: “Aonde você vai?” Ele respondeu: “Vou medir Jerusalém para ver qual é a sua largura e o seu comprimento.”", "38:2:3": "Então o anjo que falava comigo saiu, e outro anjo veio ao seu encontro.", "38:2:4": "Ele lhe disse: “Corra até lá e diga àquele jovem: ‘“Jerusalém será habitada como uma cidade sem muralhas, por causa de todos os homens e rebanhos dentro dela.", "38:2:5": "E eu”, diz Jeová, “me tornarei para ela uma muralha de fogo ao seu redor, e serei a glória no meio dela”.’”", "38:2:6": "“Venham! Venham! Fujam da terra do norte”, diz Jeová. “Pois eu espalhei vocês pelos quatro ventos dos céus”, diz Jeová.", "38:2:7": "“Venha, Sião! Fuja, você que mora com a filha de Babilônia.", "38:2:8": "Pois assim diz Jeová dos exércitos, aquele que, depois de ter sido glorificado, me enviou às nações que saqueavam vocês: ‘Aquele que toca em vocês, toca na menina do meu olho.", "38:2:9": "Pois agora sacudirei o punho contra eles, e eles se tornarão despojo para os seus próprios escravos.’ E vocês certamente saberão que Jeová dos exércitos me enviou.", "38:2:10": "“Grite de alegria, ó filha de Sião; pois estou chegando, e vou residir no seu meio”, diz Jeová.", "38:2:11": "“Naquele dia muitas nações se unirão a Jeová e se tornarão meu povo; e eu vou residir com você.” E você terá de saber que Jeová dos exércitos me enviou a você.", "38:2:12": "Jeová tomará posse de Judá como sua porção no solo sagrado, e ele voltará a escolher Jerusalém.", "38:2:13": "Fique toda a humanidade em silêncio perante Jeová, porque, da sua santa morada, ele está tomando ação.", "38:8:1": "Recebi novamente a palavra de Jeová dos exércitos:", "38:8:2": "“Assim diz Jeová dos exércitos: ‘Terei zelo de Sião, um grande zelo, e com grande furor terei zelo dela.’”", "38:8:3": "“Assim diz Jeová: ‘Voltarei para Sião e residirei em Jerusalém. E Jerusalém será chamada de cidade da verdade; e o monte de Jeová dos exércitos, de monte santo.’”", "38:8:4": "“Assim diz Jeová dos exércitos: ‘Homens e mulheres idosos voltarão a se sentar nas praças de Jerusalém, cada um com o seu bastão na mão por causa da idade avançada.", "38:8:5": "E as praças da cidade ficarão cheias de meninos e meninas brincando.’”", "38:8:6": "“Assim diz Jeová dos exércitos: ‘Embora isso possa parecer difícil demais para o restante deste povo naqueles dias, deveria parecer difícil demais também para mim?’ diz Jeová dos exércitos.”", "38:8:7": "“Assim diz Jeová dos exércitos: ‘Estou salvando o meu povo, tirando-o das terras do leste e do oeste.", "38:8:8": "E eu os trarei de volta, e eles morarão em Jerusalém; eles se tornarão o meu povo, e eu me tornarei o seu Deus em verdade e justiça.’”", "38:8:9": "“Assim diz Jeová dos exércitos: ‘Fortaleçam as suas mãos, vocês que agora ouvem estas palavras da boca dos profetas, as mesmas palavras ditas no dia em que se lançou o alicerce da casa de Jeová dos exércitos para se construir o templo.", "38:8:10": "Pois antes daquele tempo não havia pagamento pelo trabalho dos homens nem dos animais; e, por causa do inimigo, não havia segurança para ir e vir, pois eu havia posto todos os homens uns contra os outros.’", "38:8:11": "“‘Mas agora não tratarei o restante deste povo como fiz no passado’, diz Jeová dos exércitos.", "38:8:12": "‘Pois será semeada a semente da paz; a videira produzirá os seus frutos, a terra dará a sua produção, e os céus darão o seu orvalho; e eu farei com que o restante deste povo herde tudo isso.", "38:8:13": "E assim como vocês se tornaram exemplo a ser citado em maldições entre as nações, ó casa de Judá e casa de Israel, assim eu os salvarei, e vocês se tornarão uma bênção. Não tenham medo! Que as suas mãos sejam fortes.’", "38:8:14": "“Pois assim diz Jeová dos exércitos: ‘“Assim como decidi trazer a vocês calamidade quando os seus antepassados me deixaram indignado”, diz Jeová dos exércitos, “e não lamentei isso,", "38:8:15": "agora estou decidido a fazer o bem a Jerusalém e à casa de Judá. Não tenham medo!”’", "38:8:16": "“‘Estas são as coisas que vocês devem fazer: falem a verdade uns com os outros, e os julgamentos nos seus portões devem promover a verdade e a paz.", "38:8:17": "Não tramem no coração o mal uns contra os outros nem amem juramentos falsos; pois eu odeio todas essas coisas’, diz Jeová.”", "38:8:18": "Recebi novamente a palavra de Jeová dos exércitos:", "38:8:19": "“Assim diz Jeová dos exércitos: ‘O jejum do quarto mês, o jejum do quinto mês, o jejum do sétimo mês e o jejum do décimo mês serão ocasiões de exultação e alegria para a casa de Judá — festividades alegres. Portanto, amem a verdade e a paz.’", "38:8:20": "“Assim diz Jeová dos exércitos: ‘Vai chegar o dia em que povos e habitantes de muitas cidades virão;", "38:8:21": "e os habitantes de uma cidade irão aos de outra e dirão: “Vamos! Vamos suplicar o favor de Jeová e buscar a Jeová dos exércitos. Eu também estou indo.”", "38:8:22": "E muitos povos e poderosas nações virão para buscar a Jeová dos exércitos em Jerusalém e para suplicar o favor de Jeová.’", "38:8:23": "“Assim diz Jeová dos exércitos: ‘Naqueles dias, dez homens de todas as línguas das nações agarrarão, sim, agarrarão firmemente a túnica de um judeu, dizendo: “Queremos ir com vocês, pois ouvimos que Deus está com vocês.”’”", "39:3:1": "“Vejam! Enviarei o meu mensageiro, e ele preparará o caminho diante de mim. E de repente o verdadeiro Senhor, a quem vocês procuram, virá ao Seu templo; e o mensageiro do pacto, de quem vocês se agradam, virá. Ele certamente virá”, diz Jeová dos exércitos.", "39:3:2": "“Mas quem suportará o dia da sua vinda, e quem conseguirá se manter de pé quando ele aparecer? Pois ele será como o fogo do refinador e como a barrela dos lavadeiros.", "39:3:3": "E ele se sentará como um refinador e purificador de prata, e purificará os filhos de Levi; e os depurará como o ouro e como a prata, e eles certamente se tornarão para Jeová pessoas que apresentam uma oferta em justiça.", "39:3:4": "E a oferta de Judá e de Jerusalém será realmente agradável a Jeová, como nos dias do passado e como nos tempos antigos.", "39:3:5": "“Eu me chegarei a vocês para julgá-los e darei prontamente testemunho contra os feiticeiros, contra os adúlteros, contra os que juram falsamente, contra os que defraudam o trabalhador contratado, a viúva e o órfão, e contra os que se recusam a ajudar o estrangeiro. Esses não me temem”, diz Jeová dos exércitos.", "39:3:6": "“Pois eu sou Jeová; eu não mudo. E vocês são filhos de Jacó; ainda não chegaram ao seu fim.", "39:3:7": "Desde os dias dos seus antepassados vocês têm se desviado dos meus decretos e não os têm guardado. Voltem para mim, e eu voltarei para vocês”, diz Jeová dos exércitos. Mas vocês dizem: “Como voltaremos?”", "39:3:8": "“Será que um simples humano pode roubar a Deus? Mas vocês estão me roubando.” E vocês dizem: “Como te roubamos?” “Nos dízimos e nas contribuições.", "39:3:9": "Com certeza, vocês são amaldiçoados, pois estão me roubando — sim, a nação inteira está fazendo isso.", "39:3:10": "Tragam todo o dízimo ao depósito para que haja alimento na minha casa; e, por favor, ponham-me à prova nesse respeito”, diz Jeová dos exércitos, “e vejam se não abrirei para vocês as comportas dos céus e se não derramarei sobre vocês uma bênção até que não falte mais nada”.", "39:3:11": "“E vou censurar o devorador, e ele não destruirá o fruto da sua terra; e a videira no seu campo não será infrutífera”, diz Jeová dos exércitos.", "39:3:12": "“Todas as nações dirão que vocês são felizes, porque vocês se tornarão uma terra de prazer”, diz Jeová dos exércitos.", "39:3:13": "“Suas palavras contra mim foram fortes”, diz Jeová. E vocês dizem: “Como falamos contra ti?”", "39:3:14": "“Vocês dizem: ‘É inútil servir a Deus. Qual é a vantagem de cumprirmos nossas obrigações para com ele e de andarmos abatidos perante Jeová dos exércitos?", "39:3:15": "Agora consideramos felizes os que são arrogantes. Além disso, os que praticam o que é mau são bem-sucedidos. Eles se atrevem a pôr Deus à prova e conseguem se safar.’”", "39:3:16": "Então os que temiam a Jeová falavam uns com os outros, cada um com o seu próximo, e Jeová prestava atenção e escutava. E diante dele foi escrito um livro de recordação para os que temiam a Jeová e para os que meditavam no seu nome.", "39:3:17": "“Eles serão meus”, diz Jeová dos exércitos, “no dia em que eu produzir uma propriedade especial. Terei compaixão deles assim como um homem tem compaixão do seu filho, que o serve.", "39:3:18": "E vocês verão novamente a diferença entre uma pessoa justa e uma pessoa má, entre quem serve a Deus e quem não o serve”.", "40:6:1": "“Tomem cuidado para não praticar sua justiça diante dos homens a fim de ser vistos por eles; se fizerem isso, vocês não terão recompensa de seu Pai, que está nos céus.", "40:6:2": "Portanto, quando você der algo a um pobre, não toque a trombeta diante de si, como fazem os hipócritas nas sinagogas e nas ruas para serem glorificados pelos homens. Digo a vocês a verdade: Eles já têm plenamente a sua recompensa.", "40:6:3": "Mas, quando você der algo a um pobre, não deixe a sua mão esquerda saber o que a direita está fazendo,", "40:6:4": "para que suas dádivas fiquem em segredo. Então o seu Pai, que observa em secreto, o recompensará.", "40:6:5": "“Também, quando orarem, não ajam como os hipócritas, pois eles gostam de orar em pé nas sinagogas e nas esquinas das ruas principais, para serem vistos pelos homens. Digo a vocês a verdade: Eles já têm plenamente a sua recompensa.", "40:6:6": "Mas, quando você orar, entre no seu aposento reservado e, depois de fechar a porta, ore a seu Pai, que está em secreto. Então o seu Pai, que observa em secreto, o recompensará.", "40:6:7": "Quando orar, não diga as mesmas coisas vez após vez, como fazem as pessoas das nações, pois imaginam que serão ouvidas por usarem muitas palavras.", "40:6:8": "Não sejam como elas, porque o seu Pai sabe do que vocês necessitam, antes mesmo de lhe pedirem.", "40:6:9": "“Portanto, orem do seguinte modo: “‘Pai nosso, que estás nos céus, santificado seja o teu nome.", "40:6:10": "Venha o teu Reino. Seja feita a tua vontade, como no céu, assim também na terra.", "40:6:11": "Dá-nos hoje o nosso pão para este dia;", "40:6:12": "e perdoa-nos as nossas dívidas, assim como nós também perdoamos os nossos devedores.", "40:6:13": "E não nos leves à tentação, mas livra-nos do Maligno.’", "40:6:14": "“Pois, se vocês perdoarem aos homens as falhas deles, o seu Pai celestial também perdoará vocês;", "40:6:15": "ao passo que, se não perdoarem aos homens as falhas deles, o seu Pai também não perdoará as falhas de vocês.", "40:6:16": "“Quando jejuarem, parem de ficar com o rosto triste, como os hipócritas, pois eles mudam a aparência do rosto para que os homens vejam que estão jejuando. Digo a vocês a verdade: Eles já têm plenamente a sua recompensa.", "40:6:17": "Mas você, quando jejuar, ponha óleo sobre a cabeça e lave o rosto,", "40:6:18": "para que os homens não vejam que você está jejuando, mas somente o seu Pai, que está em secreto. Então o seu Pai, que observa em secreto, o recompensará.", "40:6:19": "“Parem de acumular para vocês tesouros na terra, onde a traça e a ferrugem consomem, e onde ladrões arrombam e furtam.", "40:6:20": "Em vez disso, acumulem para vocês tesouros no céu, onde nem a traça nem a ferrugem consomem, e onde ladrões não arrombam nem furtam.", "40:6:21": "Pois onde estiver o seu tesouro, ali estará também o seu coração.", "40:6:22": "“A lâmpada do corpo é o olho. Então, se o seu olho for focado, todo o seu corpo será luminoso.", "40:6:23": "Mas, se o seu olho for invejoso, todo o seu corpo será escuro. Se a luz que há em você na realidade é escuridão, como é grande essa escuridão!", "40:6:24": "“Ninguém pode ser escravo de dois senhores; pois ou odiará um e amará o outro, ou se apegará a um e desprezará o outro. Vocês não podem ser escravos de Deus e das Riquezas.", "40:6:25": "“Por essa razão, eu lhes digo: Parem de se preocupar tanto com a sua vida, quanto ao que comer ou quanto ao que beber, e com o seu corpo, quanto ao que vestir. Não significa a vida mais do que o alimento e o corpo mais do que a roupa?", "40:6:26": "Observem atentamente as aves do céu; elas não semeiam nem colhem, nem ajuntam em celeiros, contudo o Pai de vocês, que está nos céus, as alimenta. Será que vocês não valem mais do que elas?", "40:6:27": "Quem de vocês, por estar ansioso, pode acrescentar um só côvado à duração da sua vida?", "40:6:28": "Também, com respeito à roupa, por que estão ansiosos? Aprendam uma lição dos lírios do campo, de como eles crescem; não trabalham nem fiam.", "40:6:29": "Mas eu lhes digo que nem mesmo Salomão, em toda a sua glória, se vestia como um deles.", "40:6:30": "Então, se Deus veste assim a vegetação do campo, que hoje existe e amanhã é lançada no forno, não vestirá ele ainda mais a vocês, homens de pouca fé?", "40:6:31": "Portanto, nunca fiquem ansiosos, dizendo: ‘O que vamos comer?’ ou: ‘O que vamos beber?’ ou: ‘O que vamos vestir?’", "40:6:32": "Pois todas essas são as coisas pelas quais as nações se empenham ansiosamente. O seu Pai celestial sabe que vocês necessitam de todas essas coisas.", "40:6:33": "“Persistam, então, em buscar primeiro o Reino e a justiça de Deus, e todas essas outras coisas lhes serão acrescentadas.", "40:6:34": "Portanto, nunca fiquem ansiosos por causa do amanhã, pois o amanhã terá suas próprias ansiedades. Bastam a cada dia suas próprias dificuldades.", "40:24:1": "Quando Jesus estava saindo do templo, seus discípulos se aproximaram para lhe mostrar os edifícios do templo.", "40:24:2": "Em vista disso, ele lhes disse: “Não estão vendo todas estas coisas? Eu lhes digo a verdade: De modo algum ficará aqui pedra sobre pedra sem ser derrubada.”", "40:24:3": "Enquanto ele estava sentado no monte das Oliveiras, os discípulos se aproximaram dele em particular e disseram: “Diga-nos: Quando acontecerão essas coisas e qual será o sinal da sua presença e do final do sistema de coisas?”", "40:24:4": "Jesus, em resposta, lhes disse: “Cuidado para que ninguém os engane,", "40:24:5": "pois muitos virão em meu nome, dizendo: ‘Eu sou o Cristo’, e enganarão a muitos.", "40:24:6": "Vocês ouvirão falar de guerras e notícias de guerras. Cuidado para não ficar apavorados, pois essas coisas têm de acontecer, mas ainda não é o fim.", "40:24:7": "“Porque nação se levantará contra nação e reino contra reino; haverá falta de alimentos e terremotos num lugar após outro.", "40:24:8": "Todas essas coisas são um começo das dores de aflição.", "40:24:9": "“Então as pessoas os entregarão a tribulação e os matarão, e vocês serão odiados por todas as nações, por causa do meu nome.", "40:24:10": "Então, também, muitos tropeçarão, e trairão uns aos outros, e odiarão uns aos outros.", "40:24:11": "Surgirão muitos falsos profetas, que enganarão a muitos;", "40:24:12": "e, por causa do aumento do que é contra a lei, o amor da maioria esfriará.", "40:24:13": "Mas quem perseverar até o fim será salvo.", "40:24:14": "E estas boas novas do Reino serão pregadas em toda a terra habitada, em testemunho a todas as nações, e então virá o fim.", "40:24:15": "“Portanto, quando vocês virem a coisa repugnante que causa desolação, da qual falou Daniel, o profeta, estar num lugar santo (que o leitor use de discernimento),", "40:24:16": "então, os que estiverem na Judeia fujam para os montes.", "40:24:17": "O homem que estiver no terraço não desça para tirar da sua casa os bens,", "40:24:18": "e o homem que estiver no campo não volte para apanhar sua capa.", "40:24:19": "Ai das mulheres grávidas e das que amamentarem naqueles dias!", "40:24:20": "Persistam em orar para que a sua fuga não ocorra no inverno nem no sábado;", "40:24:21": "pois então haverá grande tribulação, como nunca ocorreu desde o princípio do mundo até agora, não, nem ocorrerá de novo.", "40:24:22": "De fato, se não se abreviassem aqueles dias, ninguém seria salvo; mas, por causa dos escolhidos, aqueles dias serão abreviados.", "40:24:23": "“Então, se alguém lhes disser: ‘Vejam! Aqui está o Cristo!’ ou: ‘Ali!’, não acreditem.", "40:24:24": "Porque surgirão falsos cristos e falsos profetas, e farão grandes sinais e milagres a fim de enganar, se possível, até mesmo os escolhidos.", "40:24:25": "Prestem atenção! Eu os avisei antecipadamente.", "40:24:26": "Portanto, se lhes disserem: ‘Vejam, ele está no deserto!’, não saiam; ou: ‘Vejam, ele está no interior da casa!’, não acreditem.", "40:24:27": "Pois, assim como o relâmpago sai do leste e brilha até o oeste, assim será a presença do Filho do Homem.", "40:24:28": "Onde estiver o cadáver, ali se ajuntarão as águias.", "40:24:29": "“Imediatamente depois da tribulação daqueles dias, o sol escurecerá, a lua não dará a sua luz, as estrelas cairão do céu, e os poderes dos céus serão abalados.", "40:24:30": "Então aparecerá no céu o sinal do Filho do Homem, e todas as tribos da terra então baterão no peito, de pesar, e verão o Filho do Homem vir nas nuvens do céu, com poder e grande glória.", "40:24:31": "E ele enviará seus anjos com forte som de trombeta, e eles reunirão os seus escolhidos desde os quatro ventos, de uma extremidade dos céus até a outra extremidade deles.", "40:24:32": "“Aprendam desta ilustração sobre a figueira: assim que os ramos novos ficam tenros e brotam folhas, vocês sabem que o verão está próximo.", "40:24:33": "Do mesmo modo, quando virem todas essas coisas, saibam que ele está próximo, às portas.", "40:24:34": "Eu lhes garanto que esta geração de modo algum passará até que todas essas coisas aconteçam.", "40:24:35": "Céu e terra passarão, mas as minhas palavras de modo algum passarão.", "40:24:36": "“A respeito daquele dia e daquela hora ninguém sabe, nem os anjos dos céus, nem o Filho, mas somente o Pai.", "40:24:37": "Pois, assim como eram os dias de Noé, assim será a presença do Filho do Homem.", "40:24:38": "Porque naqueles dias antes do dilúvio as pessoas comiam e bebiam, os homens se casavam e as mulheres eram dadas em casamento, até o dia em que Noé entrou na arca,", "40:24:39": "e não fizeram caso, até que veio o dilúvio e varreu a todos eles; assim será na presença do Filho do Homem.", "40:24:40": "Dois homens estarão então no campo; um será levado e o outro será abandonado.", "40:24:41": "Duas mulheres estarão moendo no moinho manual; uma será levada e a outra será abandonada.", "40:24:42": "Portanto, mantenham-se vigilantes, porque vocês não sabem em que dia virá o seu Senhor.", "40:24:43": "“Mas entendam isto: se o dono da casa soubesse em que vigília o ladrão viria, ficaria acordado e não permitiria que sua casa fosse arrombada.", "40:24:44": "Por essa razão, vocês também mostrem-se prontos, porque o Filho do Homem vem numa hora que vocês não imaginam.", "40:24:45": "“Quem é realmente o escravo fiel e prudente, a quem o seu senhor encarregou dos seus domésticos, para lhes dar o alimento no tempo apropriado?", "40:24:46": "Feliz aquele escravo se o seu senhor, quando vier, o encontrar fazendo isso!", "40:24:47": "Digo a verdade a vocês: Ele o encarregará de todos os seus bens.", "40:24:48": "“Mas, se aquele escravo mau disser no coração: ‘Meu senhor está demorando’,", "40:24:49": "e começar a espancar seus coescravos, e a comer e beber com os beberrões,", "40:24:50": "o senhor daquele escravo virá num dia em que ele não espera e numa hora que ele não sabe;", "40:24:51": "ele o punirá com a maior severidade e lhe designará um lugar entre os hipócritas. Ali é que haverá o seu choro e o ranger dos seus dentes.", "42:11:1": "Numa ocasião, ele estava em certo lugar orando e, quando parou, um dos seus discípulos lhe disse: “Senhor, ensine-nos a orar, como também João ensinou os discípulos dele.”", "42:11:2": "Ele lhes disse então: “Sempre que orarem, digam: ‘Pai, santificado seja o teu nome. Venha o teu Reino.", "42:11:3": "Dá-nos o nosso pão cada dia, segundo as nossas necessidades diárias.", "42:11:4": "E perdoa-nos os nossos pecados, pois nós mesmos também perdoamos a todo aquele que está em dívida conosco; e não nos leves à tentação.’”", "42:11:5": "Então ele lhes disse: “Digamos que um de vocês tenha um amigo e vá procurá-lo à meia-noite, e lhe diga: ‘Amigo, empreste-me três pães,", "42:11:6": "porque um amigo meu acaba de chegar de uma viagem e eu não tenho nada para lhe oferecer.’", "42:11:7": "Mas ele responde lá de dentro: ‘Pare de me incomodar. A porta já está trancada e os meus filhinhos estão comigo na cama. Não posso me levantar e lhe dar algo.’", "42:11:8": "Eu lhes digo: Ele certamente se levantará para lhe dar tudo que necessita, não por ser seu amigo, mas por causa da sua persistência e ousadia.", "42:11:9": "Portanto, eu lhes digo: Persistam em pedir, e lhes será dado; persistam em buscar, e acharão; persistam em bater, e lhes será aberto.", "42:11:10": "Pois todo aquele que pede, recebe; e todo aquele que busca, acha; e a todo aquele que bate, se abrirá.", "42:11:11": "Realmente, qual é o pai entre vocês que, se o filho lhe pedir um peixe, lhe entregará uma serpente em vez de um peixe?", "42:11:12": "Ou, se lhe pedir também um ovo, lhe entregará um escorpião?", "42:11:13": "Portanto, se vocês, embora maus, sabem dar boas coisas aos seus filhos, quanto mais o Pai, no céu, dará espírito santo aos que lhe pedirem!”", "42:11:14": "Mais tarde ele expulsou de um homem um demônio mudo. Depois de o demônio sair, o mudo falou, e as multidões ficaram maravilhadas.", "42:11:15": "Mas alguns disseram: “Ele expulsa os demônios por meio de Belzebu, o governante dos demônios.”", "42:11:16": "E outros, para testá-lo, começaram a lhe pedir um sinal do céu.", "42:11:17": "Conhecendo os pensamentos deles, ele lhes disse: “Todo reino dividido contra si mesmo cai em ruína, e uma casa dividida contra si mesma cai.", "42:11:18": "Da mesma forma, se Satanás também está dividido contra si mesmo, como o seu reino ficará de pé? Pois vocês dizem que eu expulso os demônios por meio de Belzebu.", "42:11:19": "Se eu expulso os demônios por meio de Belzebu, por meio de quem seus filhos os expulsam? É por isso que eles julgarão vocês.", "42:11:20": "Mas, se é por meio do dedo de Deus que eu expulso os demônios, o Reino de Deus realmente alcançou vocês.", "42:11:21": "Quando um homem forte, bem armado, guarda o seu palácio, seus bens ficam seguros.", "42:11:22": "Mas, quando alguém mais forte do que ele o ataca e vence, tira-lhe todas as armas em que confiava e reparte as coisas que tomou dele.", "42:11:23": "Quem não está do meu lado está contra mim, e quem comigo não ajunta, espalha.", "42:11:24": "“Quando um espírito impuro sai de um homem, ele passa por lugares áridos procurando onde descansar e, quando não acha nada, diz: ‘Voltarei para a minha casa, da qual me mudei.’", "42:11:25": "E, ao chegar, acha a casa varrida e decorada.", "42:11:26": "Então ele vai e traz consigo outros sete espíritos, piores do que ele mesmo, e, depois de entrarem, ficam morando ali. Assim, a situação final desse homem se torna pior do que no início.”", "42:11:27": "Enquanto ele dizia isso, uma mulher da multidão lhe disse bem alto: “Feliz o ventre que o carregou e os seios que o amamentaram!”", "42:11:28": "Mas ele disse: “Não, em vez disso, felizes os que ouvem a palavra de Deus e a põem em prática!”", "42:11:29": "Enquanto as multidões se aglomeravam, ele começou a dizer: “Esta geração é uma geração má. Procura um sinal, mas nenhum sinal lhe será dado, exceto o sinal de Jonas.", "42:11:30": "Pois, assim como Jonas foi um sinal para os ninivitas, assim será o Filho do Homem para esta geração.", "42:11:31": "A rainha do sul será levantada no julgamento com os homens desta geração e os condenará, porque ela veio dos confins da terra para ouvir a sabedoria de Salomão. Mas agora alguém maior do que Salomão está aqui.", "42:11:32": "Os homens de Nínive se levantarão no julgamento com esta geração e a condenarão, porque eles se arrependeram com o que Jonas pregou. Mas agora alguém maior do que Jonas está aqui.", "42:11:33": "Depois de acender uma lâmpada, a pessoa a coloca não num lugar oculto nem debaixo de um cesto, mas em cima de um suporte, para que os que entram possam ver a luz.", "42:11:34": "A lâmpada do seu corpo é o olho. Quando o seu olho é focado, todo o seu corpo também é luminoso; mas, quando é invejoso, o seu corpo também é escuro.", "42:11:35": "Por isso, tome cuidado para que a luz que há em você não seja escuridão.", "42:11:36": "Portanto, se todo o seu corpo for luminoso, sem nenhuma parte escura, todo ele será tão luminoso como uma lâmpada que ilumina você com a sua luz.”", "42:11:37": "Depois de ele ter dito isso, um fariseu lhe pediu que comesse com ele. De modo que entrou e se recostou à mesa.", "42:11:38": "No entanto, o fariseu ficou surpreso quando viu que ele não se lavou antes da refeição.", "42:11:39": "Mas o Senhor lhe disse: “Ora, vocês, fariseus, limpam por fora o copo e o prato, mas por dentro estão cheios de ganância e de maldade.", "42:11:40": "Insensatos! Aquele que fez o exterior também fez o interior, não fez?", "42:11:41": "Portanto, deem aos pobres do que está no íntimo, e então tudo a respeito de vocês será limpo.", "42:11:42": "Mas ai de vocês, fariseus, porque dão o décimo da hortelã, da arruda e de todas as outras ervas, mas desconsideram a justiça e o amor a Deus! Essas coisas vocês tinham a obrigação de fazer, mas sem desconsiderar as outras.", "42:11:43": "Ai de vocês, fariseus, porque amam os primeiros assentos nas sinagogas e os cumprimentos nas praças públicas!", "42:11:44": "Ai de vocês, porque são como aquelas sepulturas que não são facilmente vistas, e os homens andam sobre elas sem saber!”", "42:11:45": "Em resposta, um dos peritos na Lei lhe disse: “Instrutor, dizendo essas coisas, o senhor também insulta a nós.”", "42:11:46": "Ele disse então: “Ai de vocês também, peritos na Lei, porque põem sobre os homens cargas difíceis de levar, mas vocês mesmos não tocam nas cargas nem com um só dedo!", "42:11:47": "“Ai de vocês, porque constroem os túmulos dos profetas, mas os seus antepassados os mataram!", "42:11:48": "Certamente, vocês são testemunhas das ações dos seus antepassados e mesmo assim as aprovam, pois eles mataram os profetas, mas vocês constroem os túmulos deles.", "42:11:49": "É por isso que a sabedoria de Deus também disse: ‘Enviarei a eles profetas e apóstolos, e eles matarão e perseguirão alguns deles,", "42:11:50": "para que o sangue de todos os profetas, derramado desde a fundação do mundo, seja cobrado desta geração,", "42:11:51": "desde o sangue de Abel até o sangue de Zacarias, que foi morto entre o altar e a casa.’ Sim, eu lhes digo, será cobrado desta geração.", "42:11:52": "“Ai de vocês, peritos na Lei, porque se apoderaram da chave do conhecimento. Vocês mesmos não entraram e tentam impedir os que estão entrando!”", "42:11:53": "Assim, quando ele saiu dali, os escribas e os fariseus começaram a pressioná-lo fortemente e a lhe fazer muitas outras perguntas,", "42:11:54": "armando ciladas para apanhá-lo em algo que dissesse.", "43:17:1": "Jesus falou essas coisas e, levantando os olhos para o céu, disse: “Pai, chegou a hora. Glorifica o teu filho, para que o teu filho te glorifique,", "43:17:2": "assim como lhe deste autoridade sobre todas as pessoas, para que ele dê vida eterna a todos aqueles que lhe deste.", "43:17:3": "Isto significa vida eterna: que conheçam a ti, o único Deus verdadeiro, e àquele que tu enviaste, Jesus Cristo.", "43:17:4": "Eu te glorifiquei na terra e terminei a obra que me deste para fazer.", "43:17:5": "E agora, Pai, glorifica-me ao teu lado com a glória que eu tive junto de ti antes de o mundo existir.", "43:17:6": "“Tornei o teu nome conhecido aos homens que me deste do mundo. Eles eram teus, e tu os deste a mim, e eles obedeceram à tua palavra.", "43:17:7": "Agora eles sabem que todas as coisas que me deste vêm de ti,", "43:17:8": "porque eu lhes transmiti as declarações que me deste, e eles as aceitaram e certamente sabem que vim como teu representante, e acreditam que tu me enviaste.", "43:17:9": "Eu peço por eles; peço, não pelo mundo, mas por aqueles que me deste, porque eles são teus;", "43:17:10": "e todas as minhas coisas são tuas, e as tuas são minhas, e eu fui glorificado entre eles.", "43:17:11": "“Não estou mais no mundo, mas eles estão no mundo, e eu vou para ti. Santo Pai, vigia sobre eles por causa do teu nome, o nome que me deste, para que sejam um, assim como nós somos um.", "43:17:12": "Quando eu estava com eles, vigiava sobre eles por causa do teu nome, o nome que me deste; e eu os protegi, e nenhum deles foi perdido, exceto o filho da destruição, para que se cumprisse a passagem das Escrituras.", "43:17:13": "Mas agora eu vou para ti e estou falando essas coisas no mundo, para que eles sintam plenamente a minha alegria.", "43:17:14": "Eu lhes dei a tua palavra, mas o mundo os odeia, porque eles não fazem parte do mundo, assim como eu não faço parte do mundo.", "43:17:15": "“Não te peço que os tires do mundo, mas que vigies sobre eles, por causa do Maligno.", "43:17:16": "Eles não fazem parte do mundo, assim como eu não faço parte do mundo.", "43:17:17": "Santifica-os por meio da verdade; a tua palavra é a verdade.", "43:17:18": "Assim como tu me enviaste ao mundo, eu também os enviei ao mundo.", "43:17:19": "E eu me santifico em benefício deles, para que eles também sejam santificados por meio da verdade.", "43:17:20": "“Eu peço não somente por estes, mas também por aqueles que depositam fé em mim por meio das palavras deles,", "43:17:21": "para que todos sejam um, assim como tu, Pai, estás em união comigo e eu estou em união contigo, para que eles também estejam em união conosco, a fim de que o mundo acredite que tu me enviaste.", "43:17:22": "Eu lhes dei a glória que tu me deste, a fim de que eles sejam um, assim como nós somos um.", "43:17:23": "Eu em união com eles, e tu em união comigo, a fim de que estejam perfeitamente unidos, para que o mundo saiba que tu me enviaste e que os amaste assim como me amaste.", "43:17:24": "Pai, quero que aqueles que me deste estejam comigo onde eu estiver, para que possam ver a glória que me deste, porque me amaste antes da fundação do mundo.", "43:17:25": "Justo Pai, o mundo realmente não te conhece, mas eu te conheço, e estes sabem que tu me enviaste.", "43:17:26": "Eu tornei o teu nome conhecido a eles, e o tornarei conhecido, para que o amor com que me amaste esteja neles, e eu em união com eles.”", "44:2:1": "Então, durante o dia da Festividade de Pentecostes, todos eles estavam juntos no mesmo lugar.", "44:2:2": "De repente, veio do céu um barulho, bem semelhante ao de uma forte rajada de vento, e encheu toda a casa onde estavam sentados.", "44:2:3": "E eles começaram a ver o que pareciam ser línguas de fogo, e elas se espalharam e pousaram, uma sobre cada um deles;", "44:2:4": "e todos ficaram cheios de espírito santo e começaram a falar em línguas, assim como o espírito os capacitava.", "44:2:5": "Naquela ocasião estavam em Jerusalém judeus devotos, de toda nação debaixo do céu.", "44:2:6": "Assim, quando se ouviu aquele som, uma multidão se ajuntou e ficou surpresa, porque cada um ouviu os discípulos falar no seu próprio idioma.", "44:2:7": "Realmente, ficaram muito espantados e disseram: “Não são galileus todos esses que estão falando?", "44:2:8": "Como é que cada um de nós está ouvindo a sua língua nativa?", "44:2:9": "Entre nós há partos, medos e elamitas, habitantes da Mesopotâmia, da Judeia e da Capadócia, de Ponto e da província da Ásia,", "44:2:10": "da Frígia e da Panfília, do Egito e das regiões da Líbia próximas a Cirene, visitantes vindos de Roma, tanto judeus como prosélitos,", "44:2:11": "cretenses e também árabes. Nós os ouvimos falar em nossas línguas sobre as coisas magníficas de Deus.”", "44:2:12": "Sim, todos ficaram admirados e perplexos, e diziam uns aos outros: “O que significa isso?”", "44:2:13": "No entanto, outros zombavam deles e diziam: “Estão cheios de vinho doce.”", "44:2:14": "Mas Pedro se pôs de pé com os Onze e lhes falou bem alto: “Homens da Judeia e todos vocês, habitantes de Jerusalém, prestem atenção e ouçam bem as minhas palavras:", "44:2:15": "Na verdade, estas pessoas não estão bêbadas, como vocês supõem, pois é a terceira hora do dia.", "44:2:16": "Ao contrário, isto é o que foi dito por meio do profeta Joel:", "44:2:17": "‘“Nos últimos dias”, diz Deus, “derramarei do meu espírito sobre todo tipo de pessoas, e os filhos e as filhas de vocês profetizarão, os jovens entre vocês terão visões e os homens idosos entre vocês terão sonhos,", "44:2:18": "e até mesmo sobre os meus escravos e sobre as minhas escravas derramarei do meu espírito naqueles dias, e eles profetizarão.", "44:2:19": "E realizarei milagres em cima, no céu, e sinais embaixo, na terra: sangue, fogo e nuvens de fumaça.", "44:2:20": "O sol será transformado em escuridão e a lua em sangue, antes de vir o grande e glorioso dia de Jeová.", "44:2:21": "E todo aquele que invocar o nome de Jeová será salvo.”’", "44:2:22": "“Homens de Israel, ouçam estas palavras: Jesus, o Nazareno, foi um homem que Deus aprovou diante de vocês com obras poderosas, milagres e sinais que Deus fez por meio dele entre vocês, conforme sabem.", "44:2:23": "Esse homem, que foi entregue pela estabelecida vontade e presciência de Deus, vocês pregaram numa estaca pelas mãos de transgressores e o mataram.", "44:2:24": "Mas Deus o ressuscitou, livrando-o das dores da morte, porque não era possível que ela o mantivesse preso.", "44:2:25": "Pois Davi diz a respeito dele: ‘Mantenho Jeová constantemente diante de mim, pois ele está à minha direita para que eu nunca seja abalado.", "44:2:26": "Por essa razão, meu coração ficou animado e minha língua se alegrou muito. E eu viverei em esperança;", "44:2:27": "porque não me deixarás na Sepultura nem permitirás que o teu leal conheça a decomposição.", "44:2:28": "Tu me fizeste conhecer os caminhos da vida; tu me encherás de alegria na tua presença.’", "44:2:29": "“Homens, irmãos, permitam-me falar-lhes com franqueza sobre o patriarca Davi: ele morreu e foi enterrado, e seu túmulo está entre nós até o dia de hoje.", "44:2:30": "Visto que era profeta e sabia que Deus lhe havia jurado que faria um dos seus descendentes se sentar no seu trono,", "44:2:31": "ele previu a ressurreição do Cristo e falou sobre ela, que ele não seria abandonado na Sepultura e que a sua carne não conheceria a decomposição.", "44:2:32": "Deus ressuscitou a esse Jesus, e disso todos nós somos testemunhas.", "44:2:33": "Portanto, visto que ele foi enaltecido à direita de Deus e recebeu do Pai o prometido espírito santo, derramou o que vocês estão vendo e ouvindo.", "44:2:34": "Pois Davi não subiu aos céus, mas ele diz: ‘Jeová disse ao meu Senhor: “Sente-se à minha direita", "44:2:35": "até que eu ponha os seus inimigos debaixo dos seus pés.”’", "44:2:36": "Portanto, que toda a casa de Israel tenha a plena certeza de que Deus o fez Senhor e Cristo, a esse Jesus, que vocês mataram numa estaca.”", "44:2:37": "Quando ouviram isso, ficaram com o coração aflito e disseram a Pedro e aos outros apóstolos: “Homens, irmãos, o que devemos fazer?”", "44:2:38": "Pedro lhes disse: “Arrependam-se, e cada um de vocês seja batizado em nome de Jesus Cristo, para o perdão dos seus pecados, e vocês receberão a dádiva do espírito santo.", "44:2:39": "Porque a promessa é para vocês e para os seus filhos, e para todos os que estão longe, todos os que Jeová, nosso Deus, chamar para si.”", "44:2:40": "E ele dava um testemunho cabal e os exortava com muitas outras palavras, dizendo: “Sejam salvos desta geração pervertida.”", "44:2:41": "Assim, os que aceitaram com alegria as suas palavras foram batizados, e naquele dia cerca de 3.000 pessoas se juntaram a eles.", "44:2:42": "Dedicavam-se assim aos ensinamentos dos apóstolos, à convivência uns com os outros, a tomar refeições juntos e às orações.", "44:2:43": "Realmente, todos ficaram com medo, e muitos milagres e sinais começaram a ocorrer por meio dos apóstolos.", "44:2:44": "Todos os que se tornaram crentes estavam juntos e compartilhavam todas as coisas uns com os outros;", "44:2:45": "vendiam seus bens e propriedades e repartiam entre todos o valor recebido, de acordo com a necessidade de cada um.", "44:2:46": "Estavam constantemente no templo, dia após dia, unidos no mesmo propósito; tomavam as refeições nas casas uns dos outros e compartilhavam seu alimento com grande alegria e sinceridade de coração,", "44:2:47": "louvando a Deus e cativando a simpatia de todo o povo. Ao mesmo tempo, Jeová diariamente continuava a lhes acrescentar os que estavam sendo salvos.", "45:10:1": "Irmãos, o que eu realmente desejo de coração e suplico a Deus por eles é que sejam salvos.", "45:10:2": "Pois posso testemunhar que eles têm zelo por Deus, mas não segundo o conhecimento exato.", "45:10:3": "Pois, por não conhecerem a justiça de Deus, mas buscarem estabelecer a sua própria, não se sujeitaram à justiça de Deus.", "45:10:4": "Porque Cristo é o fim da Lei, para que todo aquele que exercer fé possa alcançar a justiça.", "45:10:5": "Pois Moisés escreve sobre a justiça que vem por meio da Lei: “O homem que fizer estas coisas viverá por meio delas.”", "45:10:6": "Mas a justiça resultante da fé diz: “Não diga no seu coração: ‘Quem subirá aos céus?’ isto é, para fazer Cristo descer;", "45:10:7": "ou: ‘Quem descerá ao abismo?’ isto é, para fazer Cristo subir dentre os mortos.”", "45:10:8": "Mas o que ela diz? “A palavra está perto de você, na sua própria boca e no seu próprio coração”; isto é, “a palavra” da fé, que estamos pregando.", "45:10:9": "Pois, se você declarar publicamente com a sua boca que Jesus é Senhor, e no seu coração tiver fé em que Deus o levantou dentre os mortos, você será salvo.", "45:10:10": "Porque com o coração se tem fé visando a justiça, mas com a boca se faz declaração pública visando a salvação.", "45:10:11": "Pois certa passagem das Escrituras diz: “Ninguém que basear nele a sua fé ficará decepcionado.”", "45:10:12": "Pois não há distinção entre judeu e grego; o mesmo Senhor está sobre todos e é rico para com todos os que o invocam.", "45:10:13": "Pois “todo aquele que invocar o nome de Jeová será salvo”.", "45:10:14": "Mas como o invocarão se não depositaram fé nele? E como depositarão fé naquele de quem não ouviram falar? E como ouvirão se não houver quem pregue?", "45:10:15": "Por sua vez, como pregarão, a menos que tenham sido enviados? Assim como está escrito: “Como são lindos os pés daqueles que declaram boas novas de coisas boas!”", "45:10:16": "No entanto, nem todos obedeceram às boas novas. Pois Isaías diz: “Jeová, quem depositou fé no que falamos?”", "45:10:17": "De modo que a fé segue ao que se ouve. E o que se ouve vem por meio da palavra a respeito de Cristo.", "45:10:18": "Mas eu pergunto: Será que ficaram sem ouvir? Ora, de fato, “o som deles saiu por toda a terra; e a sua mensagem, até os confins da terra habitada”.", "45:10:19": "Novamente pergunto: Será que Israel não compreendeu? Primeiro, Moisés diz: “Eu provocarei vocês ao ciúme por meio daquilo que não é nação; eu provocarei vocês à ira violenta por meio de uma nação insensata.”", "45:10:20": "E Isaías ousa dizer: “Fui achado por aqueles que não me buscavam; tornei-me conhecido pelos que não perguntavam por mim.”", "45:10:21": "Mas ele diz com respeito a Israel: “O dia inteiro estendi as mãos a um povo desobediente e obstinado.”", "46:1:1": "Paulo, chamado para ser apóstolo de Cristo Jesus pela vontade de Deus, e Sóstenes, nosso irmão,", "46:1:2": "à congregação de Deus em Corinto, a vocês que foram santificados em união com Cristo Jesus, chamados para ser santos, junto com todos os que, em toda a parte, invocam o nome do nosso Senhor Jesus Cristo, Senhor deles e nosso:", "46:1:3": "Que vocês tenham bondade imerecida e paz da parte de Deus, nosso Pai, e do Senhor Jesus Cristo.", "46:1:4": "Eu sempre agradeço ao meu Deus por vocês, em vista da bondade imerecida de Deus que lhes foi concedida em Cristo Jesus;", "46:1:5": "porque em tudo vocês foram enriquecidos nele, na plena capacidade de falar e em pleno conhecimento,", "46:1:6": "visto que o testemunho a respeito do Cristo foi firmado entre vocês,", "46:1:7": "de modo que não lhes falta nenhum dom enquanto estão esperando ansiosamente a revelação do nosso Senhor Jesus Cristo.", "46:1:8": "Também, ele os fará firmes até o fim, para que estejam livres de qualquer acusação no dia do nosso Senhor Jesus Cristo.", "46:1:9": "Deus é fiel, aquele que os chamou para estarem em união com o seu Filho, Jesus Cristo, o nosso Senhor.", "46:1:10": "Eu os exorto, irmãos, pelo nome do nosso Senhor Jesus Cristo, que todos falem de acordo e que não haja divisões entre vocês, mas que estejam completamente unidos na mesma mente e na mesma maneira de pensar.", "46:1:11": "Pois alguns da casa de Cloe me informaram a respeito de vocês, meus irmãos, que existem discórdias entre vocês.", "46:1:12": "O que eu quero dizer é que cada um de vocês diz: “Eu pertenço a Paulo”, “mas eu a Apolo”, “mas eu a Cefas”, “mas eu a Cristo”.", "46:1:13": "Por acaso o Cristo está dividido? Será que Paulo foi morto na estaca em favor de vocês? Ou, será que vocês foram batizados em nome de Paulo?", "46:1:14": "Agradeço a Deus por eu não ter batizado a nenhum de vocês, a não ser Crispo e Gaio,", "46:1:15": "para que ninguém diga que vocês foram batizados em meu nome.", "46:1:16": "Sim, batizei também os da casa de Estéfanas. Quanto aos outros, não sei se batizei mais alguém.", "46:1:17": "Pois Cristo não me enviou para batizar, mas para declarar as boas novas; e não com sabedoria de palavras, a fim de que a estaca do Cristo não se torne inútil.", "46:1:18": "Pois a mensagem a respeito da estaca é tolice para os que estão a caminho da destruição, mas para nós, que estamos sendo salvos, é o poder de Deus.", "46:1:19": "Pois está escrito: “Acabarei com a sabedoria dos sábios e rejeitarei a inteligência dos intelectuais.”", "46:1:20": "Onde está o sábio? Onde está o escriba? Onde está o argumentador deste sistema de coisas? Deus não tornou tola a sabedoria do mundo?", "46:1:21": "Pois, na sabedoria de Deus, o mundo, pela sua sabedoria, não chegou a conhecer a Deus. Portanto Deus, por meio da tolice do que se prega, se agradou de salvar os que creem.", "46:1:22": "Pois os judeus pedem sinais, e os gregos procuram sabedoria,", "46:1:23": "mas nós proclamamos Cristo morto na estaca, que para os judeus é motivo de tropeço, e para as nações é tolice.", "46:1:24": "No entanto, para os chamados, tanto judeus como gregos, Cristo é o poder de Deus e a sabedoria de Deus.", "46:1:25": "Porque uma coisa tola de Deus é mais sábia do que os homens, e uma coisa fraca de Deus é mais forte do que os homens.", "46:1:26": "Pois vocês podem ver a sua chamada da parte dele, irmãos: não há muitos sábios do ponto de vista humano, nem muitos poderosos, nem muitos de origem nobre,", "46:1:27": "mas Deus escolheu as coisas tolas do mundo para envergonhar os sábios; e Deus escolheu as coisas fracas do mundo para envergonhar as coisas fortes;", "46:1:28": "e Deus escolheu as coisas insignificantes do mundo e as coisas menosprezadas, as coisas que não são, para reduzir a nada as coisas que são,", "46:1:29": "a fim de que ninguém se orgulhe à vista de Deus.", "46:1:30": "Mas é devido a ele que vocês estão em união com Cristo Jesus, que se tornou para nós sabedoria da parte de Deus, também justiça, santificação e livramento por resgate,", "46:1:31": "para que seja assim como está escrito: “Quem se orgulhar, orgulhe-se em Jeová.”", "48:6:1": "Irmãos, mesmo que um homem, sem perceber, dê um passo em falso, vocês que têm qualificações espirituais tentem reajustar esse homem num espírito de brandura. Mas olhe cada um para si mesmo, para que não seja tentado também.", "48:6:2": "Continuem levando os fardos uns dos outros e, dessa maneira, vocês cumprirão a lei do Cristo.", "48:6:3": "Pois, se alguém acha que é alguma coisa, quando não é nada, está enganando a si mesmo.", "48:6:4": "Mas examine cada um suas próprias ações, e então terá motivo para se alegrar apenas com respeito a si mesmo, e não em comparação com outra pessoa.", "48:6:5": "Pois cada um levará a sua própria carga.", "48:6:6": "Além disso, todo aquele a quem a palavra estiver sendo ensinada, partilhe todas as coisas boas com quem lhe ensina.", "48:6:7": "Não se enganem: de Deus não se zomba. Pois o que a pessoa semear, isso também colherá;", "48:6:8": "porque aquele que semeia visando a sua carne colherá da carne destruição, mas aquele que semeia visando o espírito colherá do espírito vida eterna.", "48:6:9": "Assim, não desistamos de fazer o que é bom, pois colheremos no tempo devido, se não desanimarmos.", "48:6:10": "Então, enquanto tivermos oportunidade, façamos o bem a todos, mas especialmente aos que fazem parte da nossa família na fé.", "48:6:11": "Vejam com que grandes letras lhes escrevi com a minha própria mão.", "48:6:12": "Aqueles que querem causar uma boa impressão segundo padrões humanos são os que tentam obrigar vocês a ser circuncidados, e eles fazem isso só para não serem perseguidos por causa da estaca do Cristo.", "48:6:13": "Pois mesmo os que se submetem à circuncisão não cumprem a Lei, mas querem que vocês sejam circuncidados para que eles tenham motivo para se gabar do corpo de vocês.", "48:6:14": "No entanto, que eu nunca me orgulhe de nada, a não ser da estaca do nosso Senhor Jesus Cristo; por meio dele o mundo, para mim, está morto, e eu estou morto para o mundo.", "48:6:15": "Pois o que importa não é a circuncisão nem a incircuncisão, mas ser uma nova criação.", "48:6:16": "Que haja paz e misericórdia sobre todos os que vivem de acordo com essa regra, sim, sobre o Israel de Deus.", "48:6:17": "De agora em diante, que ninguém me cause dificuldades, pois trago no corpo as marcas de um escravo de Jesus.", "48:6:18": "Que a bondade imerecida do nosso Senhor Jesus Cristo esteja com o espírito que vocês mostram, irmãos. Amém.", "58:3:1": "Portanto, santos irmãos, participantes da chamada celestial, considerem aquele que reconhecemos como apóstolo e sumo sacerdote — Jesus.", "58:3:2": "Ele foi fiel Àquele que o designou, assim como Moisés também o foi em toda a casa Daquele.", "58:3:3": "Pois ele é considerado digno de maior glória do que Moisés, visto que quem constrói uma casa tem mais honra do que a própria casa.", "58:3:4": "Naturalmente, toda casa é construída por alguém, mas quem construiu todas as coisas foi Deus.", "58:3:5": "Moisés foi fiel como assistente em toda a casa Daquele, o que serviu de testemunho das coisas de que se falaria depois,", "58:3:6": "mas Cristo foi fiel como filho sobre a casa de Deus. Nós somos a casa Dele, desde que de fato nos apeguemos firmemente, até o fim, à nossa confiança e à esperança de que nos orgulhamos.", "58:3:7": "Portanto, como diz o espírito santo: “Hoje, se vocês escutarem a voz dele,", "58:3:8": "não endureçam o coração como na ocasião em que se provocou ira amarga, como no dia da provação no deserto,", "58:3:9": "onde os seus antepassados me puseram à prova e me desafiaram, embora tivessem visto as minhas obras por 40 anos.", "58:3:10": "É por isso que me aborreci com essa geração e disse: ‘Eles sempre se perdem no seu coração, e eles não chegaram a conhecer os meus caminhos.’", "58:3:11": "Então jurei na minha ira: ‘Não entrarão no meu descanso.’”", "58:3:12": "Cuidado, irmãos, para que nunca se desenvolva em nenhum de vocês um coração mau e sem fé, por se afastarem do Deus vivente;", "58:3:13": "mas continuem a encorajar uns aos outros cada dia, enquanto durar o tempo chamado de “hoje”, para que nenhum de vocês fique endurecido pelo poder enganoso do pecado.", "58:3:14": "Porque nós só nos tornaremos realmente participantes do Cristo se nos apegarmos firmemente até o fim à confiança que tivemos no princípio.", "58:3:15": "É como se diz: “Hoje, se vocês escutarem a voz dele, não endureçam o coração como na ocasião em que se provocou ira amarga.”", "58:3:16": "Pois quem foram os que ouviram e ainda assim provocaram Deus à ira amarga? Não foram, de fato, todos os que tinham saído do Egito sob Moisés?", "58:3:17": "Além disso, com quem Deus ficou aborrecido por 40 anos? Não foi com aqueles que pecaram, cujos cadáveres caíram no deserto?", "58:3:18": "E a quem ele jurou que não entrariam no seu descanso? Não foi aos que agiram de modo desobediente?", "58:3:19": "Vemos assim que não puderam entrar porque não tiveram fé.", "66:7:1": "Depois disso vi quatro anjos em pé nos quatro cantos da terra, segurando firmemente os quatro ventos da terra, de modo que nenhum vento pudesse soprar sobre a terra, nem sobre o mar, nem sobre árvore alguma.", "66:7:2": "E eu vi outro anjo subir do nascente, com um selo do Deus vivente, e ele gritou em alta voz para os quatro anjos aos quais havia sido concedido fazer dano à terra e ao mar:", "66:7:3": "“Não façam dano à terra, nem ao mar, nem às árvores, até termos selado na testa os escravos do nosso Deus.”", "66:7:4": "Então ouvi o número dos selados: 144.000, selados de toda tribo dos filhos de Israel:", "66:7:5": "da tribo de Judá, 12.000 selados; da tribo de Rubem, 12.000; da tribo de Gade, 12.000;", "66:7:6": "da tribo de Aser, 12.000; da tribo de Naftali, 12.000; da tribo de Manassés, 12.000;", "66:7:7": "da tribo de Simeão, 12.000; da tribo de Levi, 12.000; da tribo de Issacar, 12.000;", "66:7:8": "da tribo de Zebulão, 12.000; da tribo de José, 12.000; da tribo de Benjamim, 12.000 selados.", "66:7:9": "Depois disso eu vi uma grande multidão, que nenhum homem era capaz de contar, de todas as nações, tribos, povos e línguas, em pé diante do trono e diante do Cordeiro, vestidos de compridas vestes brancas, e havia folhas de palmeiras nas suas mãos.", "66:7:10": "Clamavam em alta voz: “Devemos a salvação ao nosso Deus, que está sentado no trono, e ao Cordeiro.”", "66:7:11": "Todos os anjos estavam em pé ao redor do trono, dos anciãos e das quatro criaturas viventes; e eles se prostraram com o rosto no chão diante do trono e adoraram a Deus,", "66:7:12": "dizendo: “Amém! O louvor, a glória, a sabedoria, o agradecimento, a honra, o poder e a força sejam ao nosso Deus para todo o sempre. Amém.”", "66:7:13": "Em vista disso, um dos anciãos me disse: “Quem são esses que vestem compridas vestes brancas, e de onde vieram?”", "66:7:14": "Assim, eu lhe disse imediatamente: “Meu senhor, é o senhor quem sabe.” Ele me disse: “Esses são os que saem da grande tribulação; eles lavaram suas vestes compridas e as embranqueceram no sangue do Cordeiro.", "66:7:15": "É por isso que estão diante do trono de Deus, e lhe prestam serviço sagrado dia e noite no seu templo; Aquele que está sentado no trono estenderá a sua tenda sobre eles.", "66:7:16": "Não terão mais fome, nem terão mais sede; e nem o sol nem o calor abrasador os castigarão,", "66:7:17": "porque o Cordeiro, que está no meio do trono, os pastoreará e os guiará a fontes de água da vida. E Deus enxugará toda lágrima dos olhos deles.”", "66:14:1": "Então vi o Cordeiro em pé no monte Sião, e com ele 144.000, que têm o nome dele e o nome do seu Pai escritos na testa.", "66:14:2": "Ouvi um som vindo do céu, como o som de muitas águas e como o som de um forte trovão; o som que ouvi era como de cantores tocando as suas harpas ao cantar.", "66:14:3": "Estavam cantando o que parecia ser um novo cântico, diante do trono e diante das quatro criaturas viventes e dos anciãos. Ninguém podia aprender esse cântico, exceto os 144.000 que foram comprados da terra.", "66:14:4": "Esses são os que não se contaminaram com mulheres; de fato, são virgens. Esses são os que estão seguindo o Cordeiro para onde quer que ele vá. Foram comprados dentre a humanidade como primícias para Deus e para o Cordeiro,", "66:14:5": "e não se achou engano na sua boca; eles não têm defeito.", "66:14:6": "Vi outro anjo voando pelo meio do céu, e ele tinha boas novas eternas para declarar aos que moram na terra, a toda nação, tribo, língua e povo.", "66:14:7": "Ele dizia em alta voz: “Temam a Deus e deem-lhe glória, porque chegou a hora do Seu julgamento. Assim, adorem Aquele que fez o céu, a terra, o mar e as fontes de água.”", "66:14:8": "A seguir veio outro anjo, um segundo, dizendo: “Caiu! Caiu Babilônia, a Grande, aquela que fazia todas as nações beber do vinho da paixão da sua imoralidade sexual!”", "66:14:9": "Outro anjo os seguiu, um terceiro, dizendo em alta voz: “Se alguém adorar a fera e a sua imagem, e receber uma marca na testa ou na mão,", "66:14:10": "beberá também do vinho da ira de Deus, que foi derramado, sem ser diluído, no cálice do seu furor, e será atormentado com fogo e enxofre à vista dos santos anjos e à vista do Cordeiro.", "66:14:11": "A fumaça do tormento deles subirá para todo o sempre; os que adoram a fera e a sua imagem, e quem recebe a marca do seu nome, não terão descanso, dia e noite.", "66:14:12": "Isso exige perseverança da parte dos santos, os que obedecem aos mandamentos de Deus e se apegam à fé em Jesus.”", "66:14:13": "E eu ouvi uma voz vinda do céu dizer: “Escreva: Felizes os mortos que, deste tempo em diante, morrem em união com o Senhor. Sim, diz o espírito, que eles descansem do seu trabalho árduo, porque as coisas que fizeram os acompanham.”", "66:14:14": "Vi então uma nuvem branca, e sobre a nuvem estava sentado alguém semelhante a um filho de homem, com uma coroa de ouro na cabeça e uma foice afiada na mão.", "66:14:15": "Outro anjo saiu do santuário do templo, gritando em alta voz para o que estava sentado na nuvem: “Use sua foice e ceife, pois chegou a hora para ceifar, porque a colheita da terra está completamente madura.”", "66:14:16": "E o que estava sentado na nuvem meteu sua foice na terra, e a terra foi ceifada.", "66:14:17": "Ainda outro anjo saiu do santuário do templo, que está no céu, e ele também tinha uma foice afiada.", "66:14:18": "Do altar saiu ainda outro anjo, e ele tinha autoridade sobre o fogo. Ele gritou em alta voz para aquele que tinha a foice afiada, dizendo: “Use sua foice afiada e colha os cachos da videira da terra, pois as uvas ficaram maduras.”", "66:14:19": "O anjo meteu sua foice na terra e ceifou a videira da terra, e a lançou no grande lagar da ira de Deus.", "66:14:20": "O lagar foi pisado fora da cidade, e saiu sangue do lagar, chegando até a altura dos freios dos cavalos, por uma distância de 1.600 estádios.", "66:16:1": "Ouvi então uma voz alta sair do santuário e dizer aos sete anjos: “Vão e derramem sobre a terra as sete tigelas da ira de Deus.”", "66:16:2": "O primeiro foi e derramou a sua tigela sobre a terra. E uma úlcera nociva e maligna afligiu as pessoas que tinham a marca da fera e adoravam a sua imagem.", "66:16:3": "O segundo derramou a sua tigela no mar. E o mar se transformou em sangue como de um morto, e morreu toda criatura vivente que havia no mar.", "66:16:4": "O terceiro derramou a sua tigela nos rios e nas fontes de água. E eles se transformaram em sangue.", "66:16:5": "Eu ouvi o anjo responsável pelas águas dizer: “Tu, Aquele que é e que era, o Leal, és justo, pois decretaste esses julgamentos,", "66:16:6": "pois eles derramaram o sangue dos santos e dos profetas, e tu lhes deste sangue para beber; isso é o que merecem.”", "66:16:7": "E eu ouvi o altar dizer: “Sim, Jeová Deus, o Todo-Poderoso, verdadeiros e justos são os teus julgamentos.”", "66:16:8": "O quarto derramou a sua tigela sobre o sol. E foi concedido ao sol abrasar as pessoas com fogo.", "66:16:9": "As pessoas foram então abrasadas pelo grande calor, mas elas blasfemaram contra o nome de Deus, que tem a autoridade sobre essas pragas, e não se arrependeram nem lhe deram glória.", "66:16:10": "O quinto derramou a sua tigela sobre o trono da fera. E o reino dela ficou em escuridão, e as pessoas começaram a morder a língua de dor,", "66:16:11": "mas blasfemaram contra o Deus do céu por causa das suas dores e das suas úlceras, e não se arrependeram das suas obras.", "66:16:12": "O sexto derramou a sua tigela sobre o grande rio Eufrates. E a água dele secou, a fim de que se preparasse o caminho para os reis do nascente do sol.", "66:16:13": "E vi três expressões inspiradas impuras, parecidas com rãs, sair da boca do dragão, da boca da fera e da boca do falso profeta.", "66:16:14": "De fato, são expressões inspiradas por demônios e realizam sinais; vão aos reis de toda a terra habitada, a fim de reuni-los para a guerra do grande dia de Deus, o Todo-Poderoso.", "66:16:15": "“Escute: Venho como um ladrão. Feliz aquele que fica desperto e conserva consigo as suas roupas, para que não ande nu e as pessoas não olhem para a sua vergonha.”", "66:16:16": "E elas os reuniram no lugar que em hebraico se chama Armagedom.", "66:16:17": "O sétimo derramou a sua tigela no ar. Então, uma voz alta saiu do santuário, desde o trono, dizendo: “Está feito!”", "66:16:18": "E houve relâmpagos, vozes e trovões, e houve um grande terremoto, diferente de todos que já tinham ocorrido desde que os homens vieram a existir na terra, de tão extenso e tão grande que foi o terremoto.", "66:16:19": "A grande cidade se fendeu em três partes, e as cidades das nações caíram. E Deus se lembrou de Babilônia, a Grande, para lhe dar o cálice com o vinho do furor da sua ira.", "66:16:20": "Também, todas as ilhas fugiram, e os montes desapareceram.", "66:16:21": "Então grandes pedras de granizo, cada uma do peso de cerca de um talento, caíram do céu sobre as pessoas, e as pessoas blasfemaram contra Deus por causa da praga de granizo, pois a praga era extraordinariamente grande.", "16:8:1": "Então todo o povo se reuniu de comum acordo na praça em frente ao Portão das Águas, e disseram a Esdras, o copista, que trouxesse o livro da Lei de Moisés, que Jeová tinha dado a Israel.", "16:8:2": "Assim, no primeiro dia do sétimo mês, Esdras, o sacerdote, trouxe o livro da Lei até a congregação, composta de homens, mulheres e todos os que eram capazes de compreender o que era dito.", "16:8:3": "E ele o leu em voz alta na praça em frente ao Portão das Águas, desde o amanhecer até o meio-dia, para os homens, as mulheres e todos os que eram capazes de compreender; e o povo ouviu atentamente a leitura do livro da Lei.", "16:8:4": "Esdras, o copista, estava de pé numa plataforma de madeira feita para a ocasião. De pé ao lado dele, à sua direita, estavam Matitias, Sema, Anaías, Urias, Hilquias e Maaseias; e à sua esquerda estavam Pedaías, Misael, Malquias, Hasum, Hasbadana, Zacarias e Mesulão.", "16:8:5": "Esdras abriu o livro à vista de todo o povo, pois ele estava num lugar mais alto do que o povo. Quando ele abriu o livro, todos se levantaram.", "16:8:6": "Esdras louvou então a Jeová, o verdadeiro Deus, o Grande, e todo o povo respondeu “Amém! Amém!” e levantou as mãos. Curvaram-se então e prostraram-se perante Jeová com o rosto por terra.", "16:8:7": "E Jesua, Bani, Serebias, Jamim, Acube, Sabetai, Hodias, Maasias, Quelita, Azarias, Jozabade, Hanã e Pelaías, que eram levitas, explicavam a Lei ao povo, que continuava de pé.", "16:8:8": "E liam em voz alta o livro, a Lei do verdadeiro Deus, explicando-a claramente e dando o sentido dela; assim ajudavam o povo a entender o que estava sendo lido.", "16:8:9": "Neemias, que era então o governador, Esdras, o sacerdote e copista, e os levitas que estavam instruindo o povo, disseram a todos eles: “O dia de hoje é santo para Jeová, seu Deus. Não lamentem nem chorem.” Pois todo o povo estava chorando ao ouvir as palavras da Lei.", "16:8:10": "Ele lhes disse: “Vão, comam as melhores comidas e tomem bebidas doces, e enviem porções de alimento aos que não têm nada preparado; pois este dia é santo para o nosso Senhor. Não fiquem tristes, pois a alegria que vem de Jeová é a fortaleza de vocês.”", "16:8:11": "E os levitas acalmavam todo o povo, dizendo: “Não chorem, pois este dia é santo; não fiquem tristes.”", "16:8:12": "Portanto, todo o povo foi embora para comer e beber; também enviaram porções de alimento a outros, e ficaram muito alegres, pois entenderam as palavras que lhes tinham sido declaradas.", "16:8:13": "E, no segundo dia, os cabeças das casas paternas de todo o povo, bem como os sacerdotes e os levitas, se reuniram ao redor de Esdras, o copista, para entender melhor as palavras da Lei.", "16:8:14": "Então encontraram escrito na Lei que Jeová, por meio de Moisés, havia ordenado que os israelitas morassem em barracas durante a festividade do sétimo mês,", "16:8:15": "e que proclamassem e anunciassem em todas as suas cidades e em Jerusalém o seguinte: “Vão à região montanhosa e tragam ramos frondosos de oliveira, de pinheiros, de murta e de palmeira, e também ramos frondosos de outras árvores, para fazer barracas, conforme está escrito.”", "16:8:16": "Então o povo foi e trouxe ramos a fim de fazer para si barracas, cada um no seu próprio terraço, bem como nos seus pátios, nos pátios da casa do verdadeiro Deus, na praça do Portão das Águas e na praça do Portão de Efraim.", "16:8:17": "Desse modo, todos da congregação que tinham voltado do cativeiro fizeram barracas e foram morar nas barracas. Os israelitas não celebravam a festividade assim desde os dias de Josué, filho de Num, até aquele dia, de modo que houve muita alegria.", "16:8:18": "E a Lei do verdadeiro Deus foi lida todos os dias, desde o primeiro dia até o último. Eles celebraram a festividade por sete dias, e houve uma assembleia solene no oitavo dia, conforme era exigido.", "17:6:1": "Naquela noite o rei perdeu o sono. Por isso, ele mandou trazer o livro dos registros históricos daqueles tempos, e o leram para o rei.", "17:6:2": "E viram que ali estava escrito que Mordecai havia denunciado Bigtana e Teres, dois oficiais da corte do rei, porteiros, que haviam planejado matar o rei Assuero.", "17:6:3": "O rei perguntou: “Que honra e reconhecimento Mordecai recebeu por isso?” Os assistentes pessoais do rei responderam: “Nada foi feito por ele.”", "17:6:4": "Mais tarde o rei perguntou: “Quem está no pátio?” Era Hamã quem tinha entrado no pátio externo da casa do rei, para lhe pedir que Mordecai fosse pendurado no madeiro que havia preparado para ele.", "17:6:5": "Os assistentes do rei responderam: “É Hamã que está no pátio.” O rei disse então: “Mandem-no entrar.”", "17:6:6": "Quando Hamã entrou, o rei lhe perguntou: “O que se deve fazer ao homem a quem o rei deseja honrar?” Hamã disse no coração: “A quem o rei desejaria honrar mais do que a mim?”", "17:6:7": "Portanto, Hamã respondeu ao rei: “Para o homem a quem o rei deseja honrar,", "17:6:8": "devem-se trazer vestes reais, que o próprio rei usa, e um cavalo em que o rei cavalga, e colocar na cabeça do cavalo um ornamento régio.", "17:6:9": "As vestes e o cavalo devem ser entregues aos cuidados de um dos príncipes mais destacados do rei, e terão de vestir o homem a quem o rei deseja honrar e fazê-lo cavalgar na praça da cidade. Deverão proclamar diante dele: ‘Assim se faz ao homem a quem o rei deseja honrar!’”", "17:6:10": "Imediatamente o rei disse a Hamã: “Vá depressa pegar as vestes e o cavalo, e faça a Mordecai, o judeu, que está sentado no portão do rei, tudo o que você acabou de falar. Não deixe de fazer nada do que você falou.”", "17:6:11": "Então Hamã pegou as vestes e o cavalo, vestiu Mordecai e o fez cavalgar na praça da cidade, proclamando diante dele: “Assim se faz ao homem a quem o rei deseja honrar!”", "17:6:12": "Depois Mordecai voltou ao portão do rei, mas Hamã foi depressa para casa, chorando e cobrindo a cabeça.", "17:6:13": "Hamã contou a Zeres, sua esposa, e a todos os seus amigos tudo o que havia acontecido com ele. Então seus sábios e Zeres, sua esposa, lhe disseram: “Se Mordecai, diante de quem você começou a cair, é de descendência judaica, você não poderá vencê-lo. Você certamente cairá diante dele.”", "17:6:14": "Enquanto ainda estavam falando com ele, chegaram os oficiais da corte do rei e imediatamente levaram Hamã ao banquete preparado por Ester.", "40:23:1": "Jesus disse então às multidões e aos seus discípulos:", "40:23:2": "“Os escribas e os fariseus se sentaram no lugar de Moisés.", "40:23:3": "Portanto, façam e cumpram tudo o que eles dizem a vocês, mas não ajam como eles, pois falam, mas não praticam o que dizem.", "40:23:4": "Amarram cargas pesadas e as põem nos ombros dos homens, mas eles mesmos não estão dispostos nem a movê-las com o dedo.", "40:23:5": "Fazem todas as suas obras para serem vistos pelos homens, pois ampliam as caixinhas com textos que usam como proteção e alongam as franjas das suas roupas.", "40:23:6": "Gostam do lugar mais destacado nos banquetes, dos primeiros assentos nas sinagogas,", "40:23:7": "dos cumprimentos nas praças públicas e de ser chamados ‘Rabi’ pelos homens.", "40:23:8": "Mas vocês não sejam chamados ‘Rabi’, pois um só é o seu Instrutor, e todos vocês são irmãos.", "40:23:9": "Além disso, não chamem a ninguém na terra de seu pai, pois um só é o seu Pai, o celestial.", "40:23:10": "Nem sejam chamados de líderes, pois o seu Líder é um só, o Cristo.", "40:23:11": "Mas o maior entre vocês tem de ser o seu servo.", "40:23:12": "Quem se enaltecer será humilhado, e quem se humilhar será enaltecido.", "40:23:13": "“Ai de vocês, escribas e fariseus, hipócritas! Porque fecham o Reino dos céus diante dos homens; pois vocês mesmos não entram, nem deixam entrar os que estão a caminho para entrar.", "40:23:14": "——", "40:23:15": "“Ai de vocês, escribas e fariseus, hipócritas! Porque percorrem o mar e a terra para fazer um prosélito e, quando conseguem, fazem dele merecedor da Geena duas vezes mais do que vocês.", "40:23:16": "“Ai de vocês, guias cegos, que dizem: ‘Se alguém jurar pelo templo, isso não é nada; mas, se alguém jurar pelo ouro do templo, ele está sob obrigação.’", "40:23:17": "Tolos e cegos! Na verdade, o que é maior: o ouro ou o templo que santifica o ouro?", "40:23:18": "Além disso, vocês dizem: ‘Se alguém jurar pelo altar, isso não é nada; mas, se alguém jurar pela dádiva nele, ele está sob obrigação.’", "40:23:19": "Cegos! Na verdade, o que é maior: a dádiva ou o altar que santifica a dádiva?", "40:23:20": "Portanto, quem jura pelo altar está jurando por ele e por todas as coisas sobre ele;", "40:23:21": "e quem jura pelo templo está jurando por ele e por Aquele que habita nele;", "40:23:22": "e quem jura pelo céu está jurando pelo trono de Deus e por Aquele que está sentado nele.", "40:23:23": "“Ai de vocês, escribas e fariseus, hipócritas! Porque dão o décimo da hortelã, do endro e do cominho, mas desconsideram as questões mais importantes da Lei, isto é, a justiça, a misericórdia e a fidelidade. Essas eram as coisas que precisavam ser feitas, mas sem desconsiderar as outras.", "40:23:24": "Guias cegos, que coam o mosquito, mas engolem o camelo!", "40:23:25": "“Ai de vocês, escribas e fariseus, hipócritas! Porque limpam por fora o copo e o prato, mas por dentro eles estão cheios de ganância e de imoderação.", "40:23:26": "Fariseu cego, limpe primeiro a parte de dentro do copo e do prato, para que a parte de fora também fique limpa.", "40:23:27": "“Ai de vocês, escribas e fariseus, hipócritas! Porque são como sepulcros caiados, que por fora realmente parecem belos, mas por dentro estão cheios de ossos de mortos e de todo tipo de impureza.", "40:23:28": "Do mesmo modo, por fora vocês parecem justos aos homens, mas por dentro estão cheios de hipocrisia e do que é contra a lei.", "40:23:29": "“Ai de vocês, escribas e fariseus, hipócritas! Porque constroem os sepulcros dos profetas e decoram os túmulos dos justos,", "40:23:30": "e dizem: ‘Se nós tivéssemos vivido nos dias dos nossos antepassados, não teríamos participado com eles em derramar o sangue dos profetas.’", "40:23:31": "Portanto, vocês dão testemunho contra si mesmos de que são filhos daqueles que assassinaram os profetas.", "40:23:32": "Pois bem, completem a medida dos seus antepassados.", "40:23:33": "“Serpentes, descendência de víboras, como fugirão do julgamento da Geena?", "40:23:34": "É por essa razão que eu estou lhes enviando profetas, sábios e instrutores públicos. A alguns deles vocês matarão e pregarão em estacas, e a outros açoitarão nas suas sinagogas e perseguirão de cidade em cidade,", "40:23:35": "para que venha sobre vocês todo o sangue justo derramado na terra, desde o sangue do justo Abel até o sangue de Zacarias, filho de Baraquias, a quem vocês assassinaram entre o santuário e o altar.", "40:23:36": "Eu garanto a vocês: Todas essas coisas virão sobre esta geração.", "40:23:37": "“Jerusalém, Jerusalém, que mata os profetas e apedreja os que lhe são enviados . . . Quantas vezes eu quis ajuntar seus filhos, assim como a galinha ajunta seus pintinhos debaixo das asas! Mas vocês não quiseram.", "40:23:38": "Agora a sua casa ficará abandonada.", "40:23:39": "Pois eu lhes digo: De agora em diante, vocês de modo algum me verão, até que digam: ‘Bendito é aquele que vem em nome de Jeová!’”", "42:12:1": "Enquanto isso, quando uma multidão de muitos milhares havia se ajuntado a ponto de atropelarem uns aos outros, ele começou a falar, dirigindo-se primeiro aos discípulos: “Tomem cuidado com o fermento dos fariseus, que é a hipocrisia.", "42:12:2": "Mas não há nada cuidadosamente oculto que não venha a ser revelado, e não há nada secreto que não se torne conhecido.", "42:12:3": "Portanto, tudo que vocês dizem na escuridão será ouvido na luz, e o que sussurram em aposentos reservados será pregado dos terraços das casas.", "42:12:4": "Além disso, eu lhes digo, meus amigos: Não temam os que matam o corpo e depois disso não podem fazer mais nada.", "42:12:5": "Mas eu lhes mostrarei a quem vocês devem temer: temam Aquele que, depois de matar, tem autoridade para lançar na Geena. Sim, eu lhes digo, temam a esse.", "42:12:6": "Não se vendem cinco pardais por duas moedas de pequeno valor? Contudo, nem mesmo um deles é esquecido por Deus.", "42:12:7": "Mas até mesmo os cabelos da cabeça de vocês estão todos contados. Não tenham medo; vocês valem mais do que muitos pardais.", "42:12:8": "“Eu lhes digo: Todo aquele que declarar diante dos homens que está em união comigo, o Filho do Homem também declarará, diante dos anjos de Deus, estar em união com ele.", "42:12:9": "Mas quem me negar diante dos homens será negado diante dos anjos de Deus.", "42:12:10": "E todo aquele que disser uma palavra contra o Filho do Homem será perdoado; mas quem blasfemar contra o espírito santo não será perdoado.", "42:12:11": "Quando levarem vocês diante de assembleias públicas, funcionários do governo e autoridades, não fiquem preocupados com o que falar ou como falar em sua defesa, ou com o que vocês dirão,", "42:12:12": "pois o espírito santo lhes ensinará naquela mesma hora o que devem dizer.”", "42:12:13": "Então alguém na multidão lhe disse: “Instrutor, diga a meu irmão que divida comigo a herança.”", "42:12:14": "Ele lhe respondeu: “Homem, quem me designou como juiz ou me deu o direito de repartir os bens entre vocês dois?”", "42:12:15": "Então lhes disse: “Mantenham os olhos abertos e resguardem-se de todo tipo de ganância, porque, mesmo quando alguém tem abundância, sua vida não vem das coisas que possui.”", "42:12:16": "Com isso, contou-lhes uma ilustração, dizendo: “A terra de um homem rico produziu bem.", "42:12:17": "Por isso, ele começou a raciocinar no íntimo: ‘O que farei agora que não tenho onde ajuntar minhas safras?’", "42:12:18": "E disse: ‘Farei o seguinte: derrubarei os meus celeiros e construirei maiores, e ali ajuntarei todo o meu cereal e todos os meus bens;", "42:12:19": "e direi a mim mesmo: “Você tem muitas coisas boas armazenadas para muitos anos. Descanse, coma, beba, divirta-se.”’", "42:12:20": "Mas Deus lhe disse: ‘Insensato, esta noite exigirão de você a sua vida. Quem terá então as coisas que você acumulou?’", "42:12:21": "Isso é o que acontece com o homem que acumula tesouros para si, mas não é rico para com Deus.”", "42:12:22": "Ele disse então aos seus discípulos: “É por isso que eu lhes digo: Parem de se preocupar tanto com a sua vida, quanto ao que comer, e com o seu corpo, quanto ao que vestir.", "42:12:23": "Pois a vida vale mais do que o alimento, e o corpo mais do que a roupa.", "42:12:24": "Vejam os corvos: eles não semeiam nem colhem, não têm nem celeiro nem depósito; contudo, Deus os alimenta. Será que vocês não valem muito mais do que as aves?", "42:12:25": "Quem de vocês, por estar ansioso, pode acrescentar um côvado à duração da sua vida?", "42:12:26": "Portanto, se vocês não podem fazer uma coisa tão pequena, por que se preocupam tanto com as outras coisas?", "42:12:27": "Vejam como os lírios crescem: eles não trabalham nem fiam; mas eu lhes digo que nem mesmo Salomão, em toda a sua glória, se vestia como um deles.", "42:12:28": "Então, se Deus veste assim a vegetação do campo, que hoje existe e amanhã é lançada no forno, quanto mais ele vestirá a vocês, homens de pouca fé!", "42:12:29": "Assim, parem de procurar o que comer e o que beber, e parem de ficar excessivamente preocupados;", "42:12:30": "porque é por todas essas coisas que as nações do mundo se empenham ansiosamente, mas o seu Pai sabe que vocês necessitam dessas coisas.", "42:12:31": "Em vez disso, continuem a buscar o Reino dele, e essas coisas lhes serão acrescentadas.", "42:12:32": "“Não tema, pequeno rebanho, porque o seu Pai se agradou de dar o Reino a vocês.", "42:12:33": "Vendam as suas coisas e deem aos pobres. Façam para vocês bolsas de dinheiro que não se gastem, um tesouro que nunca acabe, nos céus, onde o ladrão não chega perto nem a traça consome.", "42:12:34": "Pois onde estiver o seu tesouro, ali estará também o seu coração.", "42:12:35": "“Estejam vestidos e preparados, estejam com as suas lâmpadas acesas,", "42:12:36": "sejam como homens que esperam o seu senhor voltar do casamento, para que, quando ele vier e bater à porta, possam imediatamente abrir-lhe.", "42:12:37": "Felizes aqueles escravos cujo senhor, quando vier, os encontrar vigiando! Digo a verdade a vocês: Ele se vestirá para servir, fará que se recostem à mesa e virá servi-los.", "42:12:38": "E, se ele vier na segunda vigília, ou mesmo na terceira, e os encontrar preparados, felizes são!", "42:12:39": "Mas saibam que, se o dono da casa soubesse a que hora viria o ladrão, não deixaria que a sua casa fosse arrombada.", "42:12:40": "Vocês também, mantenham-se prontos, porque o Filho do Homem virá numa hora que vocês não acham provável.”", "42:12:41": "Pedro perguntou então: “Senhor, essa ilustração é só para nós ou também para todos?”", "42:12:42": "E o Senhor disse: “Quem é realmente o administrador fiel, o prudente, a quem o seu senhor encarregará do grupo de assistentes para sempre dar a eles a sua medida de mantimentos no tempo apropriado?", "42:12:43": "Feliz aquele escravo se o seu senhor, quando vier, o encontrar fazendo isso!", "42:12:44": "Digo a verdade a vocês: Ele o encarregará de todos os seus bens.", "42:12:45": "Mas, se aquele escravo disser no coração: ‘Meu senhor demora a vir’, e começar a espancar os servos e as servas, e a comer, beber e se embriagar,", "42:12:46": "o senhor daquele escravo virá num dia em que ele não espera e numa hora que ele não sabe, e o punirá com a maior severidade e lhe designará um lugar entre os infiéis.", "42:12:47": "Então aquele escravo que entendeu a vontade do seu senhor, mas não se aprontou nem fez o que ele lhe pediu, será espancado com muitos golpes.", "42:12:48": "Mas aquele que não entendeu e fez coisas que merecem punição será espancado com poucos golpes. Realmente, de todo aquele a quem muito foi dado, muito será exigido; e daquele que foi encarregado de muito, será exigido mais do que o normal.", "42:12:49": "“Eu vim para acender um fogo na terra, e o que mais posso desejar se ele já foi aceso?", "42:12:50": "Realmente, tenho um batismo com que devo ser batizado, e como estou aflito até que ele termine!", "42:12:51": "Vocês pensam que eu vim trazer paz à terra? Eu lhes digo que não! Em vez disso, vim trazer divisão.", "42:12:52": "Pois de agora em diante haverá numa casa cinco divididos uns contra os outros: três contra dois e dois contra três.", "42:12:53": "Estarão divididos, pai contra filho e filho contra pai, mãe contra filha e filha contra mãe, sogra contra nora e nora contra sogra.”", "42:12:54": "Então ele disse também às multidões: “Quando vocês veem uma nuvem surgindo no ocidente, dizem imediatamente: ‘Vem uma tempestade’, e assim acontece.", "42:12:55": "E, quando vocês veem soprar um vento sul, dizem: ‘Haverá uma onda de calor’, e assim ocorre.", "42:12:56": "Hipócritas! Vocês sabem examinar a aparência da terra e do céu, mas como é que não sabem examinar este tempo específico?", "42:12:57": "Por que não julgam também por si mesmos o que é justo?", "42:12:58": "Por exemplo, enquanto você e seu adversário estão indo a uma autoridade, empenhe-se, no caminho, em resolver a disputa com ele, para que ele não o leve perante o juiz, e o juiz o entregue ao oficial de justiça, e o oficial de justiça o lance na prisão.", "42:12:59": "Eu lhe digo: Você de modo algum sairá de lá até pagar sua última pequena moeda.”", "42:21:1": "Então, erguendo os olhos, ele viu os ricos pondo suas dádivas nos cofres do tesouro.", "42:21:2": "Viu então uma viúva necessitada pôr neles duas pequenas moedas de pouquíssimo valor", "42:21:3": "e disse: “Digo a verdade a vocês: Esta viúva pobre pôs nos cofres do tesouro mais do que todos eles.", "42:21:4": "Pois todos esses puseram dádivas do que lhes sobrava, mas ela, da sua carência, pôs tudo o que tinha para viver.”", "42:21:5": "Mais tarde, quando alguns estavam falando sobre o templo, sobre como era adornado com belas pedras e com dádivas oferecidas a Deus,", "42:21:6": "ele disse: “Quanto a estas coisas que vocês estão vendo, virão os dias em que não ficará pedra sobre pedra sem ser derrubada.”", "42:21:7": "Perguntaram-lhe então: “Instrutor, quando acontecerão realmente essas coisas e qual será o sinal de que essas coisas estão prestes a ocorrer?”", "42:21:8": "Ele disse: “Cuidado para não serem enganados, pois muitos virão em meu nome, dizendo: ‘Sou eu’, e: ‘Está próximo o tempo devido.’ Não vão atrás deles.", "42:21:9": "Além disso, quando ouvirem falar de guerras e tumultos, não fiquem apavorados. Pois essas coisas têm de acontecer primeiro, mas o fim não ocorrerá imediatamente.”", "42:21:10": "Então lhes disse: “Nação se levantará contra nação e reino contra reino.", "42:21:11": "Haverá grandes terremotos e, num lugar após outro, falta de alimentos e pestilências; e as pessoas verão coisas atemorizantes e grandes sinais do céu.", "42:21:12": "“Mas, antes que tudo isso aconteça, prenderão e perseguirão vocês, entregando-os às sinagogas e às prisões, e vocês serão levados diante de reis e governadores por causa do meu nome.", "42:21:13": "Isso resultará numa oportunidade para vocês darem testemunho.", "42:21:14": "Portanto, resolvam no coração não ensaiar antecipadamente como fazer a sua defesa,", "42:21:15": "porque eu lhes darei palavras e sabedoria, às quais todos os seus opositores juntos não poderão resistir, nem contestar.", "42:21:16": "Além disso, vocês serão entregues até mesmo por pais, irmãos, parentes e amigos, e eles entregarão alguns de vocês à morte,", "42:21:17": "e vocês serão odiados por todos, por causa do meu nome.", "42:21:18": "Mas nem um único fio de cabelo da sua cabeça se perderá.", "42:21:19": "Pela sua perseverança, vocês preservarão a sua vida.", "42:21:20": "“No entanto, quando virem Jerusalém cercada por exércitos acampados, então saibam que está próxima a desolação dela.", "42:21:21": "Então, os que estiverem na Judeia fujam para os montes, os que estiverem no meio dela saiam, e os que estiverem nos campos não entrem nela,", "42:21:22": "porque esses são dias para se executar a justiça a fim de que se cumpram todas as coisas escritas.", "42:21:23": "Ai das mulheres grávidas e das que amamentarem naqueles dias! Porque haverá grande aflição nesta terra e ira contra este povo.", "42:21:24": "E eles cairão pelo fio da espada e serão levados cativos para todas as nações; e Jerusalém será pisada pelas nações até se cumprirem os tempos determinados das nações.", "42:21:25": "“Também, haverá sinais no sol, na lua e nas estrelas; e, na terra, angústia de nações, que não saberão o que fazer por causa do rugido do mar e da sua agitação.", "42:21:26": "Pessoas desfalecerão de medo, na expectativa das coisas que vêm sobre a terra habitada, pois os poderes dos céus serão abalados.", "42:21:27": "E então verão o Filho do Homem vir numa nuvem, com poder e grande glória.", "42:21:28": "Mas, quando essas coisas começarem a ocorrer, ponham-se de pé e levantem a cabeça, porque o seu livramento está se aproximando.”", "42:21:29": "Então lhes contou uma ilustração: “Reparem na figueira e em todas as outras árvores.", "42:21:30": "Quando elas estão brotando, vocês veem e sabem por si mesmos que o verão já está próximo.", "42:21:31": "Do mesmo modo, quando virem essas coisas acontecer, saibam que o Reino de Deus está próximo.", "42:21:32": "Eu lhes garanto que esta geração de modo algum passará até que todas as coisas aconteçam.", "42:21:33": "Céu e terra passarão, mas as minhas palavras de modo algum passarão.", "42:21:34": "“Mas prestem atenção a si mesmos, para que o seu coração nunca fique sobrecarregado com o excesso no comer e no beber e com as ansiedades da vida, e de repente aquele dia os apanhe de surpresa,", "42:21:35": "como uma armadilha. Pois ele virá sobre todos os que moram na face de toda a terra.", "42:21:36": "Portanto, mantenham-se despertos, fazendo todo o tempo súplicas para que consigam escapar de todas essas coisas que têm de ocorrer e consigam ficar em pé diante do Filho do Homem.”", "42:21:37": "Assim, de dia ele ensinava no templo, mas, depois do anoitecer, saía e passava a noite no chamado monte das Oliveiras.", "42:21:38": "E todo o povo se dirigia a ele, de manhã cedo, para ouvi-lo no templo.", "44:8:1": "Saulo, por sua vez, aprovava o assassinato dele. Naquele dia começou uma grande perseguição contra a congregação em Jerusalém, e todos, exceto os apóstolos, foram espalhados pelas regiões da Judeia e de Samaria.", "44:8:2": "Homens devotos levaram Estêvão embora para o enterrar e fizeram grande lamentação por ele.", "44:8:3": "Mas Saulo começou a devastar a congregação. Ele invadia uma casa após outra, arrastando para fora tanto homens como mulheres e entregando-os à prisão.", "44:8:4": "No entanto, os que tinham sido espalhados saíram por aquela região declarando as boas novas da palavra.", "44:8:5": "Filipe desceu à cidade de Samaria e começou a pregar a eles o Cristo.", "44:8:6": "As multidões, unânimes, prestavam atenção ao que Filipe dizia; elas o escutavam e viam os sinais que ele realizava.", "44:8:7": "Pois muitos tinham espíritos impuros, e estes gritavam e saíam. Além disso, muitos paralíticos e mancos foram curados.", "44:8:8": "De modo que houve muita alegria naquela cidade.", "44:8:9": "E na cidade havia um homem chamado Simão, que antes disso havia praticado artes mágicas; ele havia deixado admirada a nação de Samaria, dizendo ser alguém grande.", "44:8:10": "Todos, desde o menor até o maior, davam-lhe atenção e diziam: “Este homem é o Poder de Deus, o chamado Grande Poder.”", "44:8:11": "Davam atenção a ele porque durante muito tempo os havia impressionado com suas artes mágicas.", "44:8:12": "Mas acreditaram em Filipe quando ele lhes declarou as boas novas a respeito do Reino de Deus e do nome de Jesus Cristo, e tanto homens como mulheres foram batizados.", "44:8:13": "O próprio Simão também se tornou crente e, depois de ser batizado, continuou com Filipe. E ele se admirava ao ver sinais e grandes obras poderosas.", "44:8:14": "Quando os apóstolos em Jerusalém ouviram dizer que Samaria havia aceitado a palavra de Deus, enviaram para lá Pedro e João,", "44:8:15": "e estes desceram e oraram para que os samaritanos recebessem espírito santo.", "44:8:16": "Porque o espírito santo ainda não tinha vindo sobre nenhum deles, mas eles só haviam sido batizados em nome do Senhor Jesus.", "44:8:17": "Então lhes impuseram as mãos, e eles começaram a receber espírito santo.", "44:8:18": "Quando Simão viu que o espírito era dado pela imposição das mãos dos apóstolos, ofereceu-lhes dinheiro,", "44:8:19": "dizendo: “Deem essa autoridade também a mim, para que todo aquele sobre quem eu impuser as mãos receba espírito santo.”", "44:8:20": "Mas Pedro lhe disse: “Pereça com você a sua prata, porque você pensou que poderia obter o dom de Deus com dinheiro.", "44:8:21": "Você não pode ter nenhuma participação nisso, porque o seu coração não é reto à vista de Deus.", "44:8:22": "Portanto, arrependa-se dessa sua maldade e suplique a Jeová que, se possível, a má intenção do seu coração seja perdoada,", "44:8:23": "pois vejo que você é um veneno amargo e um escravo da injustiça.”", "44:8:24": "Simão respondeu a eles: “Façam súplicas a Jeová por mim, para que nenhuma dessas coisas que vocês disseram venha sobre mim.”", "44:8:25": "Portanto, depois de darem testemunho de forma cabal e falarem a palavra de Jeová, partiram de volta para Jerusalém, declarando as boas novas a muitas aldeias dos samaritanos.", "44:8:26": "No entanto, o anjo de Jeová disse a Filipe: “Prepare-se e vá para o sul, para a estrada que desce de Jerusalém a Gaza.” (Essa é a estrada do deserto.)", "44:8:27": "Em vista disso, ele se preparou e foi; encontrou então um eunuco etíope, alto funcionário de Candace, rainha dos etíopes, encarregado de todo o tesouro dela. Ele tinha ido a Jerusalém para adorar", "44:8:28": "e estava voltando e, sentado no seu carro, lia em voz alta o profeta Isaías.", "44:8:29": "De modo que o espírito disse a Filipe: “Vá, aproxime-se desse carro.”", "44:8:30": "Filipe correu ao lado do carro e ouviu o eunuco lendo o profeta Isaías em voz alta. Perguntou então: “O senhor entende o que está lendo?”", "44:8:31": "Ele respondeu: “Na verdade, como posso entender a menos que alguém me oriente?” E pediu que Filipe subisse e se sentasse com ele.", "44:8:32": "A passagem das Escrituras que ele estava lendo em voz alta era: “Como uma ovelha, ele foi levado ao abate e, como um cordeiro que fica em silêncio diante do seu tosquiador, ele não abre a boca.", "44:8:33": "Durante a sua humilhação, negaram-lhe a justiça. Quem contará os detalhes da sua geração? Porque a sua vida é eliminada da terra.”", "44:8:34": "O eunuco disse então a Filipe: “Por favor, diga-me: De quem o profeta está falando? De si mesmo ou de outro homem?”", "44:8:35": "Filipe começou a falar e, partindo daquela passagem das Escrituras, declarou-lhe as boas novas a respeito de Jesus.", "44:8:36": "Ao seguirem pela estrada, chegaram a um lugar onde havia água, e o eunuco disse: “Veja! Aqui há água! O que me impede de ser batizado?”", "44:8:37": "——", "44:8:38": "Assim, mandou parar o carro, e tanto Filipe como o eunuco desceram à água; e ele o batizou.", "44:8:39": "Depois de saírem da água, o espírito de Jeová rapidamente levou Filipe embora dali, e o eunuco não voltou a vê-lo, mas seguiu caminho cheio de alegria.", "44:8:40": "Filipe, no entanto, foi parar em Asdode e, ao passar por aquela região, continuou a declarar as boas novas a todas as cidades, até chegar a Cesareia."}};
